/* Generated by tools/build-narration.cjs. Original player-facing prose; DM-only catalog. */
(() => {
'use strict';
const entries=[{"global":"ECHO_RUNBOOK","path":["1"],"field":"read","id":"departure","title":"1 · Gundren rides ahead","before":["The wagon is loaded with mining supplies and road provisions. Gundren Rockseeker checks the straps one last time while Sildar waits beside their horses. The dwarf grins, but he seems impatient to get to Phandalin. “Take this to Barthen’s Provisions. I’ll meet you there.”","Gundren turns to Donavan. “If the mine holds anything unusual, write down what you actually see before anyone decides what it is worth.” To Trista, he adds, “Make sure I come back to read his account.” To Ringgo: “Choose the safe camp over the fast one. I hired you to bring people through.”"],"after":["The wagon is loaded with mining supplies and road provisions. Gundren Rockseeker checks the straps one last time while Sildar waits beside their horses. The dwarf grins, but he seems impatient to get to Phandalin. “Take this to Barthen’s Provisions. I’ll meet you there.”","Gundren turns to Donavan. “If the mine holds anything unusual, write down what you actually see before anyone decides what it is worth.” To Trista, he adds, “Make sure I come back to read his account.” To Ringgo: “Choose the safe camp over the fast one. I hired you to bring people through.”"]},{"global":"ECHO_RUNBOOK","path":["2"],"field":"read","id":"ambush","title":"2 · Dead horses and ambush","before":["The trail bends between close woods. Two horses lie across the road ahead, dead and pierced by black-feathered arrows. Their saddlebags hang open. Neither rider is in sight."],"after":["The trail bends between close woods. Two horses lie across the road ahead, dead and pierced by black-feathered arrows. Their saddlebags hang open. Neither rider is in sight.","The open saddlebags and arrows give you more to examine than the bodies alone. Beyond the bend, trunks and tangled growth break up the view into the woods; anyone moving closer will have to choose where to stand and what to watch."]},{"global":"ECHO_RUNBOOK","path":["3"],"field":"read","id":"aftermath","title":"3 · Clues after the road fight","before":["The woods settle. The two horses still block the road. Broken brush and small tracks lead north, away from the wagon and into thicker trees.","Among the goblins’ castoffs is a rough dark stone token. One side bears a single worn word: BELOW. The other carries part of a circle rubbed almost smooth."],"after":["The woods settle. The two horses still block the road. Broken brush and small tracks lead north, away from the wagon and into thicker trees.","Among the goblins’ castoffs is a rough dark stone token. One side bears a single worn word: BELOW. The other carries part of a circle rubbed almost smooth."]},{"global":"ECHO_RUNBOOK","path":["4"],"field":"read","id":"trail","title":"4 · Goblin trail and traps","before":["The goblin trail narrows under the trees. Broken twigs and churned earth show several small creatures passed this way, with heavier marks among them. The road disappears behind you."],"after":["The goblin trail narrows under the trees. Broken twigs and churned earth show several small creatures passed this way, with heavier marks among them. The road disappears behind you.","Each disturbed patch offers a place to slow down and look, while the thicker growth limits what you can see ahead. You can keep the heavier marks in view, check the ground before committing your weight, or pause to decide how closely you want to follow."]},{"global":"ECHO_RUNBOOK","path":["5"],"field":"read","id":"cave","title":"5 · Cave mouth and approach","before":["The trail ends below a wooded hill. A shallow stream runs from a dark cave mouth, with a narrow path beside it. Briars crowd the bank. Cold water murmurs over stone."],"after":["The trail ends below a wooded hill. A shallow stream runs from a dark cave mouth, with a narrow path beside it. Briars crowd the bank. Cold water murmurs over stone.","The stream and the strip of dry ground offer different approaches to the same black opening. From outside, you can study the banks and the briars before stepping beneath the hill; the sound of running water makes the darkness beyond seem deeper."]},{"global":"ECHO_RUNBOOK","path":["6"],"field":"read","id":"blind","title":"Area 2 · Goblin blind","before":["Across the stream, the briars are thick enough to swallow the path. A board creaks faintly behind them, then goes still."],"after":["Across the stream, the briars are thick enough to swallow the path. A board creaks faintly behind them, then goes still.","The vegetation interrupts your view of whatever lies beyond it. The stream remains an obvious landmark beside the approach, but the brief creak gives you a reason to watch the cover rather than hurry past it."]},{"global":"ECHO_RUNBOOK","path":["7"],"field":"read","id":"kennel","title":"Area 3 · Kennel and wolves","before":["A sharp animal smell cuts through the damp cave air. Chains scrape against stone. Three pairs of eyes turn toward you from the dark, and low growls fill the cramped chamber."],"after":["A sharp animal smell cuts through the damp cave air. Chains scrape against stone. Three pairs of eyes turn toward you from the dark, and low growls fill the cramped chamber.","The scrape of the chains marks the animals' movements more clearly than the dim light does. There is little room to spread out here, and the growling rises when attention turns toward them. You can stop at the edge of the chamber before choosing how to approach."]},{"global":"ECHO_RUNBOOK","path":["8"],"field":"read","id":"passage","title":"Area 4 · Steep passage","before":["The main passage climbs steeply beside the stream. Spray darkens the stone, and loose rubble shifts underfoot. Above the noise, you can make out another passage crossing high overhead."],"after":["The main passage climbs steeply beside the stream. Spray darkens the stone, and loose rubble shifts underfoot. Above the noise, you can make out another passage crossing high overhead.","Water follows the slope past your boots, leaving the rising stone slick and dark. The crossing overhead is separate from the route at your feet; from here, you can judge the climb and look for movement above without knowing where either passage ends."]},{"global":"ECHO_RUNBOOK","path":["9"],"field":"read","id":"bridge","title":"Area 5 · Overpass and flood","before":["A rickety bridge crosses the passage high above the water. A small figure shifts against the shadowed ceiling. Farther upstream, the sound of pooled water presses through the cave."],"after":["A rickety bridge crosses the passage high above the water. A small figure shifts against the shadowed ceiling. Farther upstream, the sound of pooled water presses through the cave.","The bridge's boards and supports stand out against the rock when your light catches them. Below, the stream continues along the climbing passage. The figure above and the louder water ahead give you two different things to watch as you decide whether to advance."]},{"global":"ECHO_RUNBOOK","path":["9"],"field":"readAfter","id":"bridge","title":"Area 5 · Overpass and flood","before":["A heartbeat after the water’s crashing boom, a quieter pressure passes behind your eyes. Then it is gone."],"after":["A heartbeat after the water’s crashing boom, a quieter pressure passes behind your eyes. Then it is gone.","The ordinary sounds of the cave return around the fading sensation: dripping stone, your breathing, and the stream finding its channel again. Nothing in that brief feeling identifies a source. You have a moment to check one another and decide whether to mention what you noticed."]},{"global":"ECHO_RUNBOOK","path":["10"],"field":"read","id":"den","title":"Area 6 · Yeemik and Sildar","before":["A cooking fire lights an uneven cavern. Goblins look up from their meal. On a higher ledge, a battered human man is held upright by one of them. He can barely stand.","One goblin raises a hand for the others to hold. “You want the human? Then we have something to discuss.”"],"after":["A cooking fire lights an uneven cavern. Goblins look up from their meal. On a higher ledge, a battered human man is held upright by one of them. He can barely stand.","One goblin raises a hand for the others to hold. “You want the human? Then we have something to discuss.”"]},{"global":"ECHO_RUNBOOK","path":["11"],"field":"read","id":"pools","title":"Area 7 · Twin pools","before":["Two dark pools fill much of the cavern. Water presses against rough stone-and-timber dams. The waterfall’s echo makes quieter movement hard to place."],"after":["Two dark pools fill much of the cavern. Water presses against rough stone-and-timber dams. The waterfall’s echo makes quieter movement hard to place.","The rough barriers hold back a great deal of water, and the noise fills the space around them. You can inspect their visible supports, look for ground that stays out of the current, or study the onward route before putting someone beside a dam."]},{"global":"ECHO_RUNBOOK","path":["12"],"field":"read","id":"klarg","title":"Area 8 · Klarg’s cave","before":["Sacks and crates fill the far side of the cave. Smoke from a low fire climbs toward an opening above. Behind the stolen supplies, a hulking figure rises, morningstar in hand, while a wolf bares its teeth."],"after":["Sacks and crates fill the far side of the cave. Smoke from a low fire climbs toward an opening above. Behind the stolen supplies, a hulking figure rises, morningstar in hand, while a wolf bares its teeth.","The stacked goods divide the cavern into patches of cover and narrow sightlines. Firelight catches the raised weapon and the wolf's teeth, while smoke drifts toward the opening overhead. The way you entered remains behind you as you choose how to answer this reception."]},{"global":"ECHO_RUNBOOK","path":["13"],"field":"read","id":"sildar","title":"After rescue · What Sildar knows","before":["Once he can sit and breathe, Sildar looks toward the cave passage. “Gundren was taken away from here. They wanted him—and the map he carried.”"],"after":["Once he can sit and breathe, Sildar looks toward the cave passage. “Gundren was taken away from here. They wanted him—and the map he carried.”","The passage is still close enough that a voice raised here could carry farther than intended. Sildar's words give you a name and an object to ask about, but not a destination. There is time to hear him out, check what help he needs, and decide where to take the conversation."]},{"global":"ECHO_RUNBOOK","path":["14"],"field":"read","id":"close","title":"Close the session","before":["The road to Phandalin is still ahead. Gundren is still out there. For a moment, you have room to decide what matters next."],"after":["The road to Phandalin is still ahead. Gundren is still out there. For a moment, you have room to decide what matters next.","Your equipment and companions are the immediate things within reach; the rest of the journey will depend on what you choose to do with them. You can make room for someone who needs help, compare the leads you actually found, or take a moment to prepare before moving on."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["1"],"field":"read","id":"s2-arrival","title":"1 · Outside Barthen’s Provisions","before":["The road ends in a street of packed earth and old stone. A trading house stands ahead, its doorway busy with local customers. Sildar slows beside you and studies the town as if trying to remember the face of an old friend. Gundren should have been here before you. He is not. What do you do?"],"after":["The road ends in a street of packed earth and old stone. A trading house stands ahead, its doorway busy with local customers. Sildar slows beside you and studies the town as if trying to remember the face of an old friend. Gundren should have been here before you. He is not. What do you do?","The trading house offers an obvious place to ask questions or settle the delivery, while the street leaves you free to keep walking. Its traffic is ordinary enough that you can watch the doorway, approach together, or decide who will speak before going inside."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["2"],"field":"read","id":"s2-barthen","title":"2 · Barthen’s Provisions","before":["Warm lamplight falls over rope, trail food, tools, and stacks of ledgers. Behind the counter, a thin shopkeeper looks up. His welcoming smile falters as he counts the faces coming through the door. “Where is Gundren?”"],"after":["Warm lamplight falls over rope, trail food, tools, and stacks of ledgers. Behind the counter, a thin shopkeeper looks up. His welcoming smile falters as he counts the faces coming through the door. “Where is Gundren?”","The shelves are arranged for practical journeys rather than impressive purchases: coils of rope, provisions, and tools ready to be carried away. The counter is a place to set down goods or ask for help, and the shopkeeper waits to hear which business brought you through his door."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["3"],"field":"read","id":"s2-sildar","title":"3 · Sildar’s next step","before":["Sildar scans the main street. “I will ask after Iarno and find us a place to gather our thoughts. We need something firmer than a rumor before we choose a road.”"],"after":["Sildar scans the main street. “I will ask after Iarno and find us a place to gather our thoughts. We need something firmer than a rumor before we choose a road.”","The street gives him several places to begin an inquiry, but his glance does not settle on an answer. Shops, passing residents, and the possibility of a shared meeting place lie within reach. You can accompany him or agree where to find one another after making your own inquiries."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["4"],"field":"read","id":"s2-inn","title":"4 · Stonehill Inn and rumors","before":["The inn is warmer and louder than the street. Supper, wet cloaks, and low conversation crowd the common room. Several people glance toward your travel-worn gear. A child at one table stops talking mid-sentence."],"after":["The inn is warmer and louder than the street. Supper, wet cloaks, and low conversation crowd the common room. Several people glance toward your travel-worn gear. A child at one table stops talking mid-sentence.","Tables and travel-worn clothing break up the room, leaving conversations close enough to approach without addressing everyone at once. The child's sudden quiet is one detail among several. You can choose a seat, seek the keeper, or listen before deciding whose story you want to hear."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["6"],"field":"read","id":"s2-redbrands","title":"6 · Redbrand confrontation · optional","before":["Four people in dirty red cloaks drift into your path. One plants a boot on the boardwalk. Another watches the townsfolk make room without being asked. The first says, “Visitors usually learn how things work here before asking questions.” What do you do?"],"after":["Four people in dirty red cloaks drift into your path. One plants a boot on the boardwalk. Another watches the townsfolk make room without being asked. The first says, “Visitors usually learn how things work here before asking questions.” What do you do?","Their attention gives the encounter an immediate edge, but the street still offers space to speak or withdraw. Before anyone reaches for a weapon, you can look at where the strangers stand and decide whether to answer together, keep your distance, or let one person do the talking."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["8"],"field":"read","id":"s2-cellar","title":"8 · Cellar and cistern · area 1","before":["Old stone steps lead below the manor. The air is cool, and dark water rests in a deep cistern. Barrels and worn flagstones crowd the cellar. A narrow door leads farther in."],"after":["Old stone steps lead below the manor. The air is cool, and dark water rests in a deep cistern. Barrels and worn flagstones crowd the cellar. A narrow door leads farther in.","The cistern and the stored goods make this a working space rather than a grand entrance. Watch where the floor leaves room to move between them. You can examine the water, check the visible doors, or establish a position before continuing farther below the manor."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["9"],"field":"read","id":"s2-barracks","title":"9 · Redbrand barracks · area 2","before":["A lamp warms this rough sleeping room. Red cloaks hang from pegs above bedrolls and discarded boots."],"after":["A lamp warms this rough sleeping room. Red cloaks hang from pegs above bedrolls and discarded boots.","The bedding and personal clutter suggest repeated use rather than a room abandoned with the house above. The space between the sleeping places is worth noting before you enter. You can look over what is plainly visible or watch the exit while someone examines the room."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["10"],"field":"read","id":"s2-trap","title":"10 · Hall and hidden pit · area 3","before":["A dusty stone hall runs toward copper-covered double doors. Old decorative columns break up the walls."],"after":["A dusty stone hall runs toward copper-covered double doors. Old decorative columns break up the walls.","The hall gives you a direct way forward, but its floor deserves as much attention as its far end. Dust, joins in the stone, and the places where boots might fall are visible things to inspect. You can slow the group or check the route without assuming that the way is safe."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["11"],"field":"read","id":"s2-crypt","title":"11 · Crypt · area 4","before":["Three old stone coffins stand in a dusty crypt. Human skeletons in rusted armor are propped against them, and copper-covered double doors wait at the far end."],"after":["Three old stone coffins stand in a dusty crypt. Human skeletons in rusted armor are propped against them, and copper-covered double doors wait at the far end.","The stonework muffles the noise from elsewhere in the hideout, making a small movement feel unusually loud. The resting places and scattered remains offer different things to examine. You can leave them undisturbed, look for names or damage, or keep watch while another person searches."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["12"],"field":"read","id":"s2-pens","title":"12 · Slave pens · area 5","before":["Iron bars divide the chamber into cells. Two armed Redbrands stand guard. A woman and a young woman are confined to one side; a boy is held apart from them."],"after":["Iron bars divide the chamber into cells. Two armed Redbrands stand guard. A woman and a young woman are confined to one side; a boy is held apart from them.","The bars turn the room into a place of confinement rather than ordinary storage. The doors and the space beside them matter if anyone is to leave in a hurry. You can address whoever is actually present, inspect the locks, or check the surrounding route before promising a way out."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["13"],"field":"read","id":"s2-armory","title":"13 · Armory and storeroom · areas 6–7","before":["Weapon racks line one chamber; the next smells of leather, fur, and dust. Old storage here still serves someone."],"after":["Weapon racks line one chamber; the next smells of leather, fur, and dust. Old storage here still serves someone.","The arrangement of the stored equipment makes it possible to examine one part of the room without disturbing everything else. You can check what is within reach, look for markings, or study the exits. Anything useful still has to be inspected before you decide to carry it away."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["14"],"field":"read","id":"s2-crevasse","title":"14 · Crevasse and nothic · area 8","before":["The worked stone gives way to a raw split in the earth. Two narrow bridges cross the dark gap, and the space below is difficult to make out."],"after":["The worked stone gives way to a raw split in the earth. Two narrow bridges cross the dark gap, and the space below is difficult to make out.","The break in the cavern floor divides your approach into separate stretches of ground. Its edges and any visible crossing deserve a careful look before someone moves ahead. You can stop to judge the drop or keep to the near side while deciding what you want to investigate."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["15"],"field":"read","id":"s2-bugbears","title":"15 · Bugbears and Droop · area 9","before":["Three large figures occupy the room as though it belongs to them. A goblin nearby flinches at your arrival and looks ready to disappear into the floor."],"after":["Three large figures occupy the room as though it belongs to them. A goblin nearby flinches at your arrival and looks ready to disappear into the floor.","The room's sleeping places and the positions of those inside shape the space available for an approach. You have a moment to note who watches you, who avoids your gaze, and where the door sits behind you. Words are still an option before the first movement becomes an attack."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["16"],"field":"read","id":"s2-common","title":"16 · Common room · area 10","before":["Dice clatter across a scarred table. Four red-cloaked figures sit around a game, cups and coins at their elbows."],"after":["Dice clatter across a scarred table. Four red-cloaked figures sit around a game, cups and coins at their elbows.","The tables and scattered possessions make this a room people spend time in, not simply a passage to somewhere else. You can take in the faces and the gaps between the furniture before answering. Whether you listen, bluff, or confront them, their reactions are something you can actually observe."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["17"],"field":"read","id":"s2-workshop","title":"17 · Wizard’s workshop · area 11","before":["Glassware, notes, and pungent powders cover the benches."],"after":["Glassware, notes, and pungent powders cover the benches.","The worktable, shelves, and unfamiliar apparatus offer several separate lines of inquiry. You can examine the written material without assuming what the equipment does, or look over the apparatus without touching it. The ordinary routes through the room remain worth keeping clear while you investigate."]},{"global":"ECHO_SESSION2_RUNBOOK","path":["18"],"field":"read","id":"s2-glasstaff","title":"18 · Glasstaff’s quarters · area 12","before":["A better-appointed room sits beyond the rougher hideout. Papers lie beside a travel chest. Someone has been planning from here."],"after":["A better-appointed room sits beyond the rougher hideout. Papers lie beside a travel chest. Someone has been planning from here.","The desk and chest suggest different sorts of business: work done in the open and possessions kept close. You can examine what is visible, listen toward the adjoining spaces, or check the way you came. Nothing here tells you what happened after someone left without further evidence."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["1"],"field":"read","id":"s3-choice","title":"1 · Choose the lead, not the destination","before":["You have stopped at Barthen’s Provisions. Gundren is at an inn, and Trista has the rat you captured. Glasstaff escaped. What do you do next?"],"after":["You have stopped at Barthen’s Provisions. Gundren is at an inn, and Trista has the rat you captured. Glasstaff escaped. What do you do next?","The shop doorway is close at hand, while the inn and the rest of town remain separate places to visit. You can settle ordinary business first, check on the companion you left behind, or give Trista room to decide what to do with her captive. The next step belongs to you."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["2"],"field":"read","id":"s3-travel","title":"2 · Triboar Trail and Neverwinter Wood","before":["The last chimney smoke falls behind you. The trail runs between long grasses and dark stands of trees, then narrows until every snapped twig sounds close."],"after":["The last chimney smoke falls behind you. The trail runs between long grasses and dark stands of trees, then narrows until every snapped twig sounds close.","The change in the ground and the narrowing view make it worth agreeing who leads and how closely you follow. Grass gives way to cover where the trail bends, and the last clear stretch of road is now behind you. You can pause to check your bearings before taking the next turn."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["3"],"field":"read","id":"s3-agatha","title":"Optional lead · Conyberry and Agatha","before":["Beyond the ruined village, branches bend together into a low shelter. The air stills. A voice from within sounds older than the trees: “You came this far to ask me something?”"],"after":["Beyond the ruined village, branches bend together into a low shelter. The air stills. A voice from within sounds older than the trees: “You came this far to ask me something?”","The low shelter makes a close approach very different from calling out at a distance. Still branches frame the entrance, and the voice waits for an answer. You can offer your purpose plainly, choose your words with care, or keep to the edge of the clearing while you speak."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["4"],"field":"read","id":"s3-old-owl","title":"Optional lead · Old Owl Well","before":["The broken watchtower stands where you last saw Hamun Kost. What remains here depends on what the party left behind."],"after":["The broken watchtower stands where you last saw Hamun Kost. What remains here depends on what the party left behind.","The broken stone is a landmark you can recognize without deciding what happened after your departure. You can compare the ground and the tower with your last visit, look for an actual new trace, or keep watch while someone examines the place more closely."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["6"],"field":"read","id":"s3-wyvern","title":"Optional lead · Wyvern Tor","before":["The ravine and cave mouth are familiar from the camp the party cleared. What signs remain depends on what they left behind."],"after":["The ravine and cave mouth are familiar from the camp the party cleared. What signs remain depends on what they left behind.","The familiar approach gives you a point from which to compare what is here now with what you remember. The ravine and the opening remain useful landmarks. You can look for a specific change, approach the cave cautiously, or leave the cleared camp behind without searching it again."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["8"],"field":"read","id":"s3-thundertree","title":"Optional lead · Reidoth at Thundertree","before":["A weathered warning faces the road into an overgrown village. Roofs are broken, walls lean into vines, and the hilltop tower still stands above them all."],"after":["A weathered warning faces the road into an overgrown village. Roofs are broken, walls lean into vines, and the hilltop tower still stands above them all.","The warning and the tower give you landmarks before you commit to any particular building. Between the ruined walls, the growth interrupts sightlines and makes some paths clearer than others. You can read the sign, study the nearest approach, or decide how to keep your companions in view."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["9"],"field":"read","id":"s3-tt-1","title":"Thundertree 1 · Western cottage","before":["A roofless cottage crouches beneath a broad tree. Its doorway has almost vanished into weeds."],"after":["A roofless cottage crouches beneath a broad tree. Its doorway has almost vanished into weeds.","The weeds interrupt a straight approach to the doorway, and the open roof leaves the cottage exposed to the sky. You can examine the nearer ground, look through the ruined walls, or keep watch beneath the broad tree before choosing how to enter."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["10"],"field":"read","id":"s3-tt-2","title":"Thundertree 2 · Blighted cottages","before":["Two collapsed homes stand side by side, their old rooms given over to brush and young trees."],"after":["Two collapsed homes stand side by side, their old rooms given over to brush and young trees.","The brush has grown across what used to separate the homes' rooms. Fallen walls still mark their old boundaries beneath the living growth. You can inspect a particular patch of rubble or keep together where the route between the two ruins is easiest to see."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["11"],"field":"read","id":"s3-tt-3","title":"Thundertree 3 · The Brown Horse","before":["A faded horse sign hangs above the door of an old tavern. Inside, forms slump against the walls and beneath the bar."],"after":["A faded horse sign hangs above the door of an old tavern. Inside, forms slump against the walls and beneath the bar.","The hanging sign gives the ruin a name even though its hospitality is long gone. The slumped forms are visible among the remains of ordinary tavern furnishings. You can stop at the doorway to study them, call into the room, or decide where to stand before entering."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["12"],"field":"read","id":"s3-tt-4","title":"Thundertree 4 · Reidoth’s watch","before":["One cottage seems to have resisted the years. Its shutters are stout, and someone has cleared the growth near the door."],"after":["One cottage seems to have resisted the years. Its shutters are stout, and someone has cleared the growth near the door.","The cleared approach and sturdy shutters set this house apart from its neighbors. They give you somewhere to knock or call without pushing through the overgrowth. You can announce yourselves, inspect the outside, or wait at a respectful distance for someone to answer."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["13"],"field":"read","id":"s3-tt-5","title":"Thundertree 5 · Blighted farmhouse","before":["The farmhouse walls have collapsed into a knot of gorse. Something small shifts in the leaves when you disturb the stones."],"after":["The farmhouse walls have collapsed into a knot of gorse. Something small shifts in the leaves when you disturb the stones.","The tangle of shrubs hides parts of the ground where the walls once stood. The movement in the leaves is brief enough to invite attention rather than an immediate explanation. You can stop disturbing the stones, look for a clearer position, or watch the growth while discussing the approach."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["14"],"field":"read","id":"s3-tt-6","title":"Thundertree 6 · Ruined store and webs","before":["White strands cross the lane to a broken store. The building looks empty from outside, though its walls offer plenty of shadows."],"after":["White strands cross the lane to a broken store. The building looks empty from outside, though its walls offer plenty of shadows.","The strands cross the lane as well as the building, making the approach itself worth examining. Your light catches some threads more readily than the shadows behind them. You can study the webbing from clear ground or decide how much of the lane you want to cross."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["15"],"field":"read","id":"s3-tt-7","title":"Thundertree 7 · Venomfang’s tower","before":["A broken tower rises above two spider corpses. The air around it smells sharp and wrong; the upper roof is open to the sky."],"after":["A broken tower rises above two spider corpses. The air around it smells sharp and wrong; the upper roof is open to the sky.","The dead spiders give the tower's sharp smell a more tangible companion. Broken stone and the open upper roof offer places to look before you approach the entrance. You can keep your distance, seek another view of the structure, or pause to decide what danger you are willing to meet."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["16"],"field":"read","id":"s3-tt-8","title":"Thundertree 8 · Old smithy","before":["Rotten wood and a wide chimney mark the old forge. Two ash-covered shapes slump where the anvils once stood."],"after":["Rotten wood and a wide chimney mark the old forge. Two ash-covered shapes slump where the anvils once stood.","The chimney remains a landmark above the rotten construction, while the shapes inside sit among the traces of old work. You can watch them from the entrance, inspect the nearby ground, or listen before disturbing the room. The forge's former purpose does not explain its present occupants."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["17"],"field":"read","id":"s3-tt-9","title":"Thundertree 9 · Herbalist’s shop","before":["Broken bottles and unreadable books fill an old shop. Mirna’s description points you toward the storage shelves."],"after":["Broken bottles and unreadable books fill an old shop. ","Glass fragments and damaged pages share the floor beneath the shelving. You can examine one storage place at a time rather than overturn the whole room. If someone has given you a description to follow, you can compare it with what you actually see here."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["18"],"field":"read","id":"s3-tt-10","title":"Thundertree 10 · Town square","before":["A leaning warrior statue watches over a square almost swallowed by brush. Paths leave in several directions."],"after":["A leaning warrior statue watches over a square almost swallowed by brush. Paths leave in several directions.","The warrior's pose remains visible despite the statue's lean, and the paths offer several different ways to leave the square. You can study the carving, check your bearings against the surrounding ruins, or choose the next approach with the whole group in sight."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["19"],"field":"read","id":"s3-tt-11","title":"Thundertree 11 · Old garrison","before":["An old stone barracks still has a roof and narrow windows. Rusted armor lies among the beds."],"after":["An old stone barracks still has a roof and narrow windows. Rusted armor lies among the beds.","The surviving roof makes the barracks feel more enclosed than the cottages outside. Narrow windows admit limited views, while beds and old armor divide the interior. You can stop to examine the threshold, look over the room, or listen before touching any of the remains."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["20"],"field":"read","id":"s3-tt-12","title":"Thundertree 12 · Weaver’s cottage","before":["A broken loom sits in a cottage open to the weather. Thick growth hides the ground beyond its southern wall."],"after":["A broken loom sits in a cottage open to the weather. Thick growth hides the ground beyond its southern wall.","The broken loom identifies one kind of work once done here. Beyond it, the southern growth conceals ground you cannot yet judge. You can examine the cottage's visible remains or keep back from the thicket while deciding where to direct your attention."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["21"],"field":"read","id":"s3-tt-13","title":"Thundertree 13 · Dragon cultists","before":["The shutters of this apparently empty house are barred from within. You hear low voices behind them."],"after":["The shutters of this apparently empty house are barred from within. You hear low voices behind them.","The voices make the barred shutters more than a sign of an abandoned house. They offer a chance to speak before attempting to get inside. You can call from the approach, listen for a response, or stand where the occupants can see you if they choose to look out."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["22"],"field":"read","id":"s3-castle-sight","title":"3 · Cragmaw Castle comes into view","before":["The trees give way to a low rise. Seven broken towers crowd around a ruined stronghold. The place looks abandoned until you catch a small movement behind a narrow slit in the stone."],"after":["The trees give way to a low rise. Seven broken towers crowd around a ruined stronghold. The place looks abandoned until you catch a small movement behind a narrow slit in the stone.","The broken upper stonework does not make the lower walls transparent. Trees still provide places to stop and observe, while the rise exposes anyone who crosses it. You can count visible approaches, watch the slit for another movement, or withdraw to discuss a quieter route."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["24"],"field":"read","id":"s3-area1","title":"Area 1 · Entrance and sentries","before":["Shattered gate timbers lie across an old entrance. Above the wreckage, narrow slots stare out from two small chambers."],"after":["Shattered gate timbers lie across an old entrance. Above the wreckage, narrow slots stare out from two small chambers.","The wrecked timbers interrupt a straight walk through the entrance. The narrow openings above offer views into the approach without giving you the same view back. You can study the wall from cover, look for a clearer way through, or decide who will cross the exposed ground first."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["25"],"field":"read","id":"s3-area2","title":"Area 2 · Falling rubble","before":["A wide hall disappears into half-light. Dust lies thick around a pile of fallen plaster, and closed doors lead away on either side."],"after":["A wide hall disappears into half-light. Dust lies thick around a pile of fallen plaster, and closed doors lead away on either side.","The fallen plaster marks one part of the floor as different from the rest. Beyond it, the closed doors give you choices without revealing what lies behind them. You can inspect the ground, listen at a door, or choose a position that keeps the entrance in sight."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["26"],"field":"read","id":"s3-area4","title":"Area 4 · Ruined barracks","before":["Broken stone has swallowed much of the tower, but bedrolls and a narrow cleared path show that someone still sleeps here."],"after":["Broken stone has swallowed much of the tower, but bedrolls and a narrow cleared path show that someone still sleeps here.","The cleared strip and the bedding are more recent signs than the fallen masonry around them. You can follow the space someone has made through the rubble or stop to examine how it is being used. The damaged tower offers no assurance that everyone inside is asleep or absent."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["27"],"field":"read","id":"s3-area5","title":"Area 5 · Storeroom and Sildar’s gear","before":["Spoiled provisions and old casks crowd the room. Among them lie a bloodied coat of mail, a crossbow, and a sword bearing a familiar crest."],"after":["Spoiled provisions and old casks crowd the room. Among them lie a bloodied coat of mail, a crossbow, and a sword bearing a familiar crest.","The recognizable equipment is within a room still crowded by old stores. You can examine its markings and condition without deciding how it came here. The casks and provisions break up the floor around it, so someone can watch the entrance while another person investigates."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["28"],"field":"read","id":"s3-area6","title":"Area 6 · Hobgoblin barracks","before":["This room is surprisingly orderly. Weapons hang on brackets above four pallets, and the floor has been swept clear of rubble."],"after":["This room is surprisingly orderly. Weapons hang on brackets above four pallets, and the floor has been swept clear of rubble.","The swept floor and arranged weapons stand out against the ruin you passed on the way here. The pallets leave recognizable places to rest and narrow spaces to move between them. You can inspect the room from its edge or check which visible exit you want watched."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["29"],"field":"read","id":"s3-area7","title":"Area 7 · Banquet hall","before":["Once a grand hall, this chamber now smells of stale food and a neglected brazier. Goblin voices rise around two scarred tables."],"after":["Once a grand hall, this chamber now smells of stale food and a neglected brazier. Goblin voices rise around two scarred tables.","The two tables take up much of the social space, with the neglected brazier drawing stale smells around it. The voices give you something to listen to before you answer them. You can remain at the edge, make your presence clear, or take stock of the route back out."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["30"],"field":"read","id":"s3-area8","title":"Area 8 · Dark hall and grick","before":["A narrow, lightless hall bears carvings that do not match its current occupants. Heavy curtains hang to the north, and a stone brazier stands between them."],"after":["A narrow, lightless hall bears carvings that do not match its current occupants. Heavy curtains hang to the north, and a stone brazier stands between them.","The carvings reward a closer look, but the curtains prevent you from seeing the spaces beyond them. The stone brazier is a visible landmark between those covered openings. You can study the workmanship, listen toward the cloth, or decide whether to move farther into the hall."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["31"],"field":"read","id":"s3-area9","title":"Area 9 · Goblin shrine","before":["A stone altar lies beneath a blood-dark cloth. A goblin in ritual scraps fusses over gold-colored implements while two acolytes watch the curtains."],"after":["A stone altar lies beneath a blood-dark cloth. A goblin in ritual scraps fusses over gold-colored implements while two acolytes watch the curtains.","The cloth hides much of the altar's surface, while the implements catch what light reaches the room. The watchers' attention rests on the curtains as well as on you. You can address them from where you stand, inspect what is visible, or withdraw before disturbing the arrangement."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["32"],"field":"read","id":"s3-area10","title":"Area 10 · South postern gate","before":["An overgrown path climbs toward an iron door protected by the wall above it. Narrow slits overlook the approach."],"after":["An overgrown path climbs toward an iron door protected by the wall above it. Narrow slits overlook the approach.","The door offers a more contained approach than the wrecked main entrance, but the slits still overlook the ground before it. Brush crowds the path around your feet. You can examine the door and wall from a distance or decide how to approach without assuming the entrance is unwatched."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["33"],"field":"read","id":"s3-area11","title":"Area 11 · Concealed north entrance","before":["A fallen tower lies under dusty canvas and brush. A few old crates remain where a storeroom once stood."],"after":["A fallen tower lies under dusty canvas and brush. A few old crates remain where a storeroom once stood.","The canvas and vegetation break up the outline of what the tower used to be. The crates are the clearest remaining sign of its practical use. You can examine a visible patch of ground, check beneath accessible cover, or keep the ruined approach in sight while someone searches."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["34"],"field":"read","id":"s3-area12","title":"Area 12 · Guard barracks","before":["Four pallets line a cramped guardroom. A coal brazier glows, and a curtain conceals an arch to the north."],"after":["Four pallets line a cramped guardroom. A coal brazier glows, and a curtain conceals an arch to the north.","The brazier's glow reaches the pallets more readily than it reaches beyond the hanging cloth. The curtain separates what you can see from what you can only hear. You can pause to listen, examine the guardroom, or decide who will stand nearest the covered arch."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["35"],"field":"read","id":"s3-area13","title":"Area 13 · Owlbear tower","before":["Something heavy shifts beyond the barred door. The wood shudders once, then a low animal breath fills the silence."],"after":["Something heavy shifts beyond the barred door. The wood shudders once, then a low animal breath fills the silence.","The barred door gives you a boundary you can choose to keep. The weight behind it is audible before it is visible, and the wood's movement gives you reason to judge your distance. You can listen, examine the fastening, or leave the barrier intact while discussing another route."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["36"],"field":"read","id":"s3-area14","title":"Area 14 · Grol and Vyerith","before":["Voices cut through the door: a harsh demand, then a smooth reply. Inside, furs cover the floor while a towering bugbear argues with a dark-clad visitor."],"after":["Voices cut through the door: a harsh demand, then a smooth reply. Inside, furs cover the floor while a towering bugbear argues with a dark-clad visitor.","The argument reveals different voices, not an agreement you understand yet. The furs and the speakers' positions divide the room into places to approach or avoid. You can listen for a few more words, announce yourselves, or look for a position that keeps your way out clear."]},{"global":"ECHO_SESSION3_RUNBOOK","path":["37"],"field":"read","id":"s3-warband","title":"Optional consequence · Returning war band","before":["Boots and low voices approach through the trees. A returning patrol has found the castle less quiet than it expected."],"after":["Boots and low voices approach through the trees. A returning patrol has found the castle less quiet than it expected.","The approaching sounds give you time to look toward cover and the route you used to reach the castle. How clearly you can see the patrol depends on where you stand. You can wait to learn more, call out, or decide whether to leave before the meeting becomes unavoidable."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["1"],"field":"read","id":"s4-arrival","title":"Arrival · follow a route the party actually earned","before":["The foothills close around the trail. Ahead, a dark opening cuts beneath the rock. Cold air brushes past you, and from somewhere below comes a low crash, like surf heard through the earth."],"after":["The foothills close around the trail. Ahead, a dark opening cuts beneath the rock. Cold air brushes past you, and from somewhere below comes a low crash, like surf heard through the earth.","The opening offers a visible threshold, but the sound beyond it reaches farther than your sight. The rocky approach gives you a place to check equipment and gather your light before entering. You can study the ground, agree on your order, or listen for the next distant surge."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["2"],"field":"read","id":"s4-room-1","title":"Area 1 · Rockseeker camp and the descent","before":["Three bedrolls surround a silent camp. Supplies lie where their owners left them. A dwarf’s body rests among the bundles, and a rope tied around a stone spire drops into a break in the cavern floor."],"after":["Three bedrolls surround a silent camp. Supplies lie where their owners left them. A dwarf’s body rests among the bundles, and a rope tied around a stone spire drops into a break in the cavern floor.","The rope is the clearest connection between this camp and the space below. Its fastening and the edge of the pit can be examined before anyone descends. The bundles and the body offer separate questions, and you can leave room for someone to keep watch while the others decide where to begin."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["3"],"field":"read","id":"s4-room-2","title":"Area 2 · Mine tunnels","before":["Low passages cross and divide ahead of you. Tool marks stop abruptly at unfinished stone faces. Between the turns, even your footsteps seem to lose their direction."],"after":["Low passages cross and divide ahead of you. Tool marks stop abruptly at unfinished stone faces. Between the turns, even your footsteps seem to lose their direction.","The low stonework makes every turn feel close, and the unfinished faces give several branches a similar appearance. You can keep a mark at the last junction, follow the group carefully, or stop to compare the visible passages before choosing one. Your route back is something you can record as you go."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["4"],"field":"read","id":"s4-room-3","title":"Area 3 · Old entrance and ceiling stirges","before":["Carved miners still work along the walls above a floor strewn with ancient bones. Empty brass lamps hang in the stone. Beyond them, the high ceiling disappears into shadow."],"after":["Carved miners still work along the walls above a floor strewn with ancient bones. Empty brass lamps hang in the stone. Beyond them, the high ceiling disappears into shadow.","The abandoned lamps offer no light of their own. Your illumination catches the miners' carved tools and the pale bones at different heights, leaving the upper space harder to judge. You can inspect the floor, examine the figures on the walls, or direct your attention toward the ceiling."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["5"],"field":"read","id":"s4-room-4","title":"Area 4 · Old guardroom","before":["Stone bunks and splintered racks lie beneath a fallen section of ceiling. Bones are scattered between them, half buried in pale dust."],"after":["Stone bunks and splintered racks lie beneath a fallen section of ceiling. Bones are scattered between them, half buried in pale dust.","The bunks identify this as a place where people once slept, while the broken racks suggest equipment no longer fit for use. Fallen stone interrupts parts of the floor. You can study the room from the threshold, choose a route through the debris, or examine a particular set of remains."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["6"],"field":"read","id":"s4-room-5","title":"Area 5 · Assayers’ office","before":["Three dusty scales stand on a stone counter. Paper scraps fill small niches behind it, and the floor holds the remains of workers and warriors who never left."],"after":["Three dusty scales stand on a stone counter. Paper scraps fill small niches behind it, and the floor holds the remains of workers and warriors who never left.","The arrangement of the scales and niches suggests work that once involved careful measurements and records. The scraps are within reach, but their age is visible in their edges. You can look without touching, search the counter, or ask someone who knows the writing to examine what survives."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["7"],"field":"read","id":"s4-room-6","title":"Area 6 · South barracks","before":["Rows of stone bunks flank an old brazier. Three gaunt shapes crouch over the scattered bones, working their jaws against scraps far too old to feed them."],"after":["Rows of stone bunks flank an old brazier. Three gaunt shapes crouch over the scattered bones, working their jaws against scraps far too old to feed them.","The bunks and old brazier break the chamber into narrower gaps than its size first suggests. The shapes among the bones are occupied with what lies before them. You can stop at the entrance to judge those gaps, choose where to stand, or decide whether to make your presence known."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["8"],"field":"read","id":"s4-room-7","title":"Area 7 · Ruined storeroom and a secure rest","before":["A collapsed wall opens onto a small chamber. Beyond a half-open door, a surviving storeroom holds neat rows of cracked, empty kegs. Its stonework is sound."],"after":["A collapsed wall opens onto a small chamber. Beyond a half-open door, a surviving storeroom holds neat rows of cracked, empty kegs. Its stonework is sound.","The half-open door breaks the line of the collapsed wall. Beyond it, cracked kegs still stand in something like their old order, a small island of storage amid the ruin. The sound of stonework carries here; its source remains out of sight."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["9"],"field":"read","id":"s4-room-8","title":"Area 8 · Fungi cavern and poison gas","before":["Pale caps, thick stalks, and shelves of fungus crowd the cavern. Some growths glow green, casting enough light to reveal the far wall. The floor between them is almost lost beneath the carpet."],"after":["Pale caps, thick stalks, and shelves of fungus crowd the cavern. Some growths glow green, casting enough light to reveal the far wall. The floor between them is almost lost beneath the carpet.","The faint green light clings to the caps and stalks, leaving the room's edges hard to judge. The growth covers the walking surface as well as the view ahead. Before crossing, you can study its spread from the threshold and decide how close to bring your light."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["10"],"field":"read","id":"s4-room-9","title":"Area 9 · Great cavern","before":["The hall opens around long stone tables and cold braziers. Stairs climb to ledges at either end, above a floor scattered with the remains of an ancient battle."],"after":["The hall opens around long stone tables and cold braziers. Stairs climb to ledges at either end, above a floor scattered with the remains of an ancient battle.","Cold braziers offer no warmth to the long tables. The stairs and ledges at either end rise above the scattered remains, giving the chamber more than one level to watch. Anything moving across the open floor would be difficult to overlook from above."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["11"],"field":"read","id":"s4-room-10","title":"Area 10 · Dark pool","before":["Still black water fills the cave. Pale broken shells crunch along the bank, and a slow stream slides away beneath a low opening to the northeast."],"after":["Still black water fills the cave. Pale broken shells crunch along the bank, and a slow stream slides away beneath a low opening to the northeast.","The bank's shells crunch beneath a careful step, while the black water gives little sense of its depth. The stream's low northeastern opening draws your eye away from the pool. Following it would mean approaching stone and water that conceal what lies beyond."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["12"],"field":"read","id":"s4-room-11","title":"Area 11 · North barracks","before":["Heat from a glowing brazier touches your face. Stone bunks line the walls, and a broken table has been piled against the eastern door."],"after":["Heat from a glowing brazier touches your face. Stone bunks line the walls, and a broken table has been piled against the eastern door.","The brazier's warmth sets this room apart from the colder passages. Bunks leave narrow spaces between them, and the broken table piled against the eastern door makes that exit a practical obstacle. You can inspect the barricade from this side before deciding whether to disturb it."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["13"],"field":"read","id":"s4-room-12","title":"Area 12 · Smelter cavern","before":["A cold furnace towers above abandoned ore carts. Beside it, a motionless wheel hangs over a dry channel. Green fire dances around a skull suspended above the armored dead."],"after":["A cold furnace towers above abandoned ore carts. Beside it, a motionless wheel hangs over a dry channel. Green fire dances around a skull suspended above the armored dead.","Ore carts stand idle beside the furnace, and the wheel hangs motionless over a dry channel. Green fire outlines the skull and catches on the armored dead. The old machinery divides the floor into working spaces; the threat now occupies the same ground where miners once labored."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["14"],"field":"read","id":"s4-room-13","title":"Area 13 · Starry cavern","before":["Your light scatters across a ceiling that glitters like a field of stars. Below it stand two battered stone buildings, blackened by fire, amid the fallen dead."],"after":["Your light scatters across a ceiling that glitters like a field of stars. Below it stand two battered stone buildings, blackened by fire, amid the fallen dead.","Points of light prick the ceiling above the two blackened buildings. Down below, fallen bodies and scorched stone tell a harsher story. The buildings interrupt the open cavern, each offering a closer approach and a separate interior to examine."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["15"],"field":"read","id":"s4-room-14","title":"Area 14 · Mormesk and the wizards’ quarters","before":["Charred furniture stands beneath a sagging ceiling. A scorched chest waits beside a ruined bed. As you step in, darkness gathers out of the floor and turns toward you."],"after":["Charred furniture stands beneath a sagging ceiling. A scorched chest waits beside a ruined bed. As you step in, darkness gathers out of the floor and turns toward you.","Charred furniture crowds the room beneath the damaged ceiling. The bed and chest survived the destruction well enough to recognize, though their contents cannot be judged from here. The dark presence near the floor draws attention away from them, making the threshold a useful place to stop and look."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["16"],"field":"read","id":"s4-room-15","title":"Area 15 · Forge of Spells and its guardian","before":["Scorched worktables ring a workshop that should have fallen silent centuries ago. Yet green flame still moves in a brazier at its heart. Above it, a many-eyed creature turns, and a greeting sounds inside your mind."],"after":["Scorched worktables ring a workshop that should have fallen silent centuries ago. Yet green flame still moves in a brazier at its heart. Above it, a many-eyed creature turns, and a greeting sounds inside your mind.","The brazier's green light colors the scorched tables, while the many-eyed creature hangs within the ruined workspace. Its greeting reaches you without crossing the air. There is room to answer before moving closer; the surviving forge equipment remains something to study rather than claim on sight."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["17"],"field":"read","id":"s4-room-16","title":"Area 16 · Booming cavern","before":["The passage ends above churning water. A surge races through the dark and strikes beneath the ledge with a crash you feel in your chest. Then the water sinks back, leaving a long, hollow roar."],"after":["The passage ends above churning water. A surge races through the dark and strikes beneath the ledge with a crash you feel in your chest. Then the water sinks back, leaving a long, hollow roar.","Each surge changes the sound of the cavern, filling the spaces between words before falling away again. The water and the stone around it are visible things to study. You can keep back from its edge, watch the rhythm, or inspect the route without entering the water."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["18"],"field":"read","id":"s4-room-17","title":"Area 17 · Old streambed bypass","before":["A dry channel squeezes beneath a low ceiling. Smooth stones and rounded boulders mark the course water once followed through the dark."],"after":["A dry channel squeezes beneath a low ceiling. Smooth stones and rounded boulders mark the course water once followed through the dark.","Smooth stones lie among larger boulders in the dry channel. With the ceiling hanging low, the route asks you to watch both your footing and your head. Its bends and obstructions break the view ahead; you can keep track of the way back as you pass them."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["19"],"field":"read","id":"s4-room-18","title":"Area 18 · Collapsed cavern and Vhalak","before":["Water spills down into a broad rift. Ropes hang from stakes along its western edge, while the clack of shifted rubble rises from below. Figures work under the eye of a dark-clad supervisor."],"after":["Water spills down into a broad rift. Ropes hang from stakes along its western edge, while the clack of shifted rubble rises from below. Figures work under the eye of a dark-clad supervisor.","The waterfall fills the rift with a steady roar, broken by the clacking work below. Ropes fastened to stakes on the western side offer a visible means of descent. From the edge, you can examine their condition and the figures beneath before committing to the drop."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["20"],"field":"read","id":"s4-room-19","title":"Area 19 · Temple of Dumathoin","before":["Six cracked pillars frame a hall swept clean of rubble. At the far end, a seated dwarf carved from stone watches over a rough camp. Bedrolls, packs, and a paper-covered table show that this shrine has become someone’s headquarters."],"after":["Six cracked pillars frame a hall swept clean of rubble. At the far end, a seated dwarf carved from stone watches over a rough camp. Bedrolls, packs, and a paper-covered table show that this shrine has become someone’s headquarters.","The figures and stonework draw your eye to different parts of the room. You can note where everyone stands and which route remains behind you before answering. The distance between you and anyone present is something to consider while there is still time to speak."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["21"],"field":"read","id":"s4-nezznar","title":"Nezznar · bargain, battle, escape, or capture","before":["The dark elf rests one hand on a spider-carved staff. “You have cost me people, time, and secrecy. Before either of us wastes more, tell me what you believe you came here to claim.”"],"after":["The dark elf rests one hand on a spider-carved staff. “You have cost me people, time, and secrecy. Before either of us wastes more, tell me what you believe you came here to claim.”","The words being exchanged do not settle what either side will accept. You can hold your position, ask for a specific answer, or make your own terms clear. The chamber and the route behind you remain part of the conversation, even if nobody chooses to mention them."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["22"],"field":"read","id":"s4-room-20","title":"Area 20 · Rescue Nundro","before":["Beyond the locked door, faded cloth hangs above a simple bed. A dwarf lies bound on the cold floor. His breathing is faint but steady."],"after":["Beyond the locked door, faded cloth hangs above a simple bed. A dwarf lies bound on the cold floor. His breathing is faint but steady.","You can take stock from the threshold before approaching what lies within. The visible condition of any person here and the space around them matter more than guessing what happened out of sight. You can offer help, ask a question, or check the way out before moving someone."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["28"],"field":"read","id":"s4-homecoming","title":"Phandalin · choose the homecoming that happened","before":["Phandalin’s roofs appear beyond the fields. Someone by the road looks up, recognizes you, and hurries toward town. By the time you reach the first houses, people are waiting to hear what happened."],"after":["Phandalin’s roofs appear beyond the fields. Someone by the road looks up, recognizes you, and hurries toward town. By the time you reach the first houses, people are waiting to hear what happened.","The places you recognize offer somewhere to begin your account, but the people who hear it will need your words. You can tell them what you witnessed, ask what changed during your absence, or settle a practical need before deciding what comes after the expedition."]},{"global":"ECHO_SESSION4_RUNBOOK","path":["29"],"field":"read","id":"s4-custody","title":"Phandalin · a living Black Spider in custody","before":["The cell door closes. For the first time, the Spider’s reach is measured in a few feet of stone. Outside, questions arrive faster than the guards can answer them."],"after":["The cell door closes. For the first time, the Spider’s reach is measured in a few feet of stone. Outside, questions arrive faster than the guards can answer them.","The cell's closed door places a boundary between the prisoner and everyone outside. Questions can wait long enough to decide who stands watch and who speaks. Whatever answer Nezznar offers will still need to be weighed against what you have actually seen."]},{"global":"ECHO_STAGE6","path":["beats","0"],"field":"read","id":"s5-open","title":"Opening · Barthen’s Provisions","before":["The noise of Phandalin follows you to Barthen’s door: cart wheels on packed earth, a hammer somewhere farther down the street, and voices turning toward the day’s business. Gundren is at an inn behind you. Glasstaff is gone. The shop is here in front of you. What do you do?"],"after":["The noise of Phandalin follows you to Barthen’s door: cart wheels on packed earth, a hammer somewhere farther down the street, and voices turning toward the day’s business. Gundren is at an inn behind you. Glasstaff is gone. The shop is here in front of you. What do you do?","The shop's threshold is close enough to cross, but you have not yet chosen to enter. You can begin with town business, turn back toward the inn, or stop to discuss the rat in Trista's care. For now, the street leaves each of those choices open."]},{"global":"ECHO_STAGE6","path":["beats","1"],"field":"read","id":"s5-barthen","title":"Lead · Business with Barthen","before":["Rope coils hang beside trail rations and stacks of useful things. Barthen lays down a pencil as you approach. “Tell me what you need,” he says, looking from one face to the next."],"after":["Rope coils hang beside trail rations and stacks of useful things. Barthen lays down a pencil as you approach. “Tell me what you need,” he says, looking from one face to the next.","The counter offers room to set down goods or explain what brought you here. Barthen waits for your account rather than supplying one of his own. You can ask for ordinary equipment, discuss the supplies, or tell him only as much of your recent trouble as you choose."]},{"global":"ECHO_STAGE6","path":["beats","2"],"field":"read","id":"s5-inn","title":"Lead · Check on Gundren at the inn","before":["The common room is busy enough that your return draws only a few glances. Somewhere beyond it is the room where you left Gundren."],"after":["The common room is busy enough that your return draws only a few glances. Somewhere beyond it is the room where you left Gundren.","The place you left him is the first thing to check, before any questions about the wider trouble. You can ask the keeper to take you there, find out who has been nearby, or arrange for someone to watch the approach. Gundren's present condition is something you must see for yourselves."]},{"global":"ECHO_STAGE6","path":["beats","3"],"field":"read","id":"s5-rat","title":"Lead · The captured rat","before":["Trista has the rat you captured in the hideout. How are you keeping it, and what do you want to try?"],"after":["Trista has the rat you captured in the hideout. How are you keeping it, and what do you want to try?","The rat's containment is something you can check before beginning an examination. What you know so far comes from the capture, not from any explanation it has given you. You can observe it, ask Trista what help she wants, or leave the question for another meeting."]},{"global":"ECHO_STAGE6","path":["beats","4"],"field":"read","id":"s5-redbrand","title":"Optional · Redbrand aftermath and witnesses","before":["The town has not forgotten the gang. A few people watch the street carefully, and the manor stands apart from the ordinary bustle. Where do you look first?"],"after":["The town has not forgotten the gang. A few people watch the street carefully, and the manor stands apart from the ordinary bustle. Where do you look first?","The manor is a landmark, not an account of what remains inside it. People who were actually present may have different parts of the story. You can choose a particular witness, return along a known approach, or turn toward another town matter without settling the gang's future here and now."]},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","0"],"field":"read","id":"um1-1","title":"Entrywell","before":"Sand covers the floor below the well; battered shields line the walls. A passage leads away into darkness.","after":"Sand covers the floor below the well; battered shields line the walls. A passage leads away into darkness.\n\nThe well above is a visible link to the world you left, while the sand records each new step beneath it. The shields offer battered surfaces to examine along the walls. You can check the landing, study the passage, or look back up before leaving the chamber."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","1"],"field":"read","id":"um1-2","title":"Hall of Many Pillars","before":"Demon reliefs flank the corridor. Beyond shallow steps, pillars break your view of the room.","after":"Demon reliefs flank the corridor. Beyond shallow steps, pillars break your view of the room.\n\nThe pillars interrupt a clear view across the room, and the shallow steps mark a change in the floor beneath you. Your light follows the demon carvings more easily than it follows the spaces between the columns. You can stop at the descent and choose what to watch."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","2"],"field":"read","id":"um1-3","title":"Slanted Room","before":"Foul water deepens across a sloping floor. A dim violet glow outlines a damaged fishlike statue.","after":"Foul water deepens across a sloping floor. A dim violet glow outlines a damaged fishlike statue.\n\nThe slope carries the foul water toward deeper parts of the floor. The violet light makes the damaged figure visible without explaining what the statue was meant to do. You can study it from the shallower ground or look for a practical route around the water."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","3"],"field":"read","id":"um1-4","title":"With Sword in Hand","before":"A faintly shining sword stands in a wooden support. Small bones lie nearby, and distant voices drift through overhead vents.","after":"A faintly shining sword stands in a wooden support. Small bones lie nearby, and distant voices drift through overhead vents.\n\nThe sword and its support stand apart from the small remains on the floor. Above, the vents carry sound from a space you cannot see. You can listen without touching the weapon, inspect the bones, or examine how the wooden support holds the blade."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","4"],"field":"read","id":"um1-5","title":"Grell Hideout","before":"Blackened pillars of mortared bone divide the room. Deep alcoves open above scattered remains.","after":"Blackened pillars of mortared bone divide the room. Deep alcoves open above scattered remains.\n\nThe bones have been worked into the pillars themselves, while other remains lie loose below them. The alcoves give your light several dark recesses to reach into. You can inspect one opening at a time or keep to a position where you can watch the room around you."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","5"],"field":"read","id":"um1-6","title":"Undertakers’ Watch Post","before":"Three stone nobles watch over broken bones and a snapped staff. Light and voices come from adjoining chambers.","after":"Three stone nobles watch over broken bones and a snapped staff. Light and voices come from adjoining chambers.\n\nThe stone figures have outlasted the broken objects at their feet. Their fixed expressions contrast with the living sound from the adjoining spaces. You can listen before approaching that light, inspect the damaged staff, or decide how plainly to announce yourselves."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","6"],"field":"read","id":"um1-7","title":"Vampire Haven","before":"Faded frescoes show people fleeing a vast bat. Dust and abandoned bedding fill the passage.","after":"Faded frescoes show people fleeing a vast bat. Dust and abandoned bedding fill the passage.\n\nThe frescoes repeat their frightened movement even where age has worn away the color. Bedding lies beneath the painted scene, leaving old decoration and more practical use side by side. You can examine the art, check the abandoned resting places, or continue along the passage."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","7"],"field":"read","id":"um1-8","title":"Bandit Headquarters","before":"Wyvern remains and crystal fragments lie below a high bone throne. Nearby rooms glow with lantern light.","after":"Wyvern remains and crystal fragments lie below a high bone throne. Nearby rooms glow with lantern light.\n\nThe high seat draws your eye upward, but the crystal fragments and remains make the floor worth watching as well. Lantern light reaches from the nearby rooms without showing everything inside them. You can inspect the debris or pause to listen before following the glow."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","8"],"field":"read","id":"um1-9","title":"Plundered Halls","before":"Empty settings pockmark the pillars. A body lies beside discarded weapons.","after":"Empty settings pockmark the pillars. A body lies beside discarded weapons.\n\nThe empty sockets in the pillars offer a pattern to examine separately from the body on the floor. Discarded weapons lie close enough to suggest questions, not answers. You can check the remains, study the stripped stonework, or watch the room while someone searches."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","9"],"field":"read","id":"um1-10","title":"Cubicle of Skulls","before":"As the door shifts, pale skulls spill across the threshold.","after":"As the door shifts, pale skulls spill across the threshold.\n\nThe skulls roll and knock against one another before settling among the dust. The doorway is now partly crowded by what fell through it. You can keep back while the movement stops, examine the exposed threshold, or look into the space the door has opened."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","10"],"field":"read","id":"um1-11","title":"Room of Secrets","before":"A green copper helm lies before a slender copper throne, both filmed with cobwebs.","after":"A green copper helm lies before a slender copper throne, both filmed with cobwebs.\n\nThe copper catches the light through the film of age, giving the throne and helm a muted green sheen. Cobwebs connect details that may once have mattered to whoever used the seat. You can inspect the workmanship or judge the surrounding floor before approaching the throne."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","11"],"field":"read","id":"um1-12","title":"Hall of Heroes","before":"Rows of battered warrior statues stand under a webbed ceiling. Dead spiders lie pierced with bolts.","after":"Rows of battered warrior statues stand under a webbed ceiling. Dead spiders lie pierced with bolts.\n\nThe statues form repeated shapes beneath the hanging webs, and the bolts make the dead spiders more than a passing detail. You can look for a clear way between the figures, examine the visible missiles, or keep your light directed toward the ceiling."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","12"],"field":"read","id":"um1-13","title":"Empty Room","before":"The short passage ends in a bare stone room.","after":"The short passage ends in a bare stone room.\n\nThe end wall gives this room a clear boundary, and the passage you entered remains the obvious way back. There is no grand furnishing to draw your eye away from the stone itself. You can examine its surfaces or leave it as a useful landmark on your route."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","13"],"field":"read","id":"um1-14","title":"Little Box of Horrors","before":"Beyond a descending passage, a four-armed fishlike statue holds a stone box beneath a suspended, shimmering pool.","after":"Beyond a descending passage, a four-armed fishlike statue holds a stone box beneath a suspended, shimmering pool.\n\nThe suspended water is above the statue rather than resting in a basin at its feet. The box and the figure's four arms give you specific parts to examine. You can remain in the passage, study the arrangement, or choose a closer position without touching it."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","14"],"field":"read","id":"um1-15","title":"Armory","before":"Collapsed racks and cobwebs surround a door with a handaxe embedded in it.","after":"Collapsed racks and cobwebs surround a door with a handaxe embedded in it.\n\nThe fallen racks interrupt the floor on the way to the door. The handaxe marks a particular place in the wood that you can inspect before opening anything. You can look over the surrounding debris or listen beyond the barrier before deciding what to try."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","15"],"field":"read","id":"um1-16","title":"Manticore Den","before":"Soiled fabric, broken stone and gnawed bones form three great nests.","after":"Soiled fabric, broken stone and gnawed bones form three great nests.\n\nThe nests are built from things that once belonged elsewhere: cloth, broken stone, and bones brought together in heaps. Their size is easier to judge than their owners' whereabouts. You can examine an edge from a distance or keep clear of the piles while checking the chamber."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","16"],"field":"read","id":"um1-17","title":"Stone Temple Pileup","before":"Beyond a dead six-legged reptile, lifelike figures cluster beneath a high temple ceiling. One dark statue gleams.","after":"Beyond a dead six-legged reptile, lifelike figures cluster beneath a high temple ceiling. One dark statue gleams.\n\nThe figures have poses that invite a closer look, while the dark statue catches light differently from the rest. The dead reptile is another visible detail to examine rather than an explanation for the whole room. You can study the scene without stepping among the figures."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","17"],"field":"read","id":"um1-18","title":"Troll’s Den","before":"The stench thickens along the passage toward a filthy chamber.","after":"The stench thickens along the passage toward a filthy chamber.\n\nThe smell reaches you before a clear view of the chamber does. The nearer floor and the mouth of the room offer places to stop and look. You can listen, inspect the approach, or decide whether to announce your presence before entering the filth."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","18"],"field":"read","id":"um1-19","title":"Ye Olde Feast Halls","before":"Stone tables and bare hanging rods fill the old halls.","after":"Stone tables and bare hanging rods fill the old halls.\n\nThe tables and rods suggest old work, but their present emptiness leaves its purpose for you to investigate. You can follow the arrangement of the stone furniture, look for marks where things once hung, or keep to the open floor while checking the adjoining halls."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","19"],"field":"read","id":"um1-20","title":"Beyond the Green Door","before":"A green wooden door bears a smiling iron face.","after":"A green wooden door bears a smiling iron face.\n\nThe iron face turns an ordinary-looking barrier into something worth examining. Its smile does not show what waits on the other side. You can inspect the visible fittings, speak from a distance, or listen at the door before deciding whether to try it."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","20"],"field":"read","id":"um1-21","title":"Hall of Mirrors","before":"Oval mirrors line the corridor, with an old torch stub on the floor.","after":"Oval mirrors line the corridor, with an old torch stub on the floor.\n\nThe mirrors repeat the corridor and the light you bring into it, making the walls seem less solid than the floor beneath your boots. The spent torch is a small, tangible detail amid those reflections. You can inspect a surface or study the ground without trusting every image equally."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","21"],"field":"read","id":"um1-22","title":"Empty Room","before":"Burnt torch ends and empty bottles mark an old stopping place.","after":"Burnt torch ends and empty bottles mark an old stopping place.\n\nThe spent torches and empty bottles show that someone stopped here, but not that they will return. You can examine the traces, note the approach, or discuss whether this is a place worth checking more carefully. A recognizable resting place is not a promise of safety."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","22"],"field":"read","id":"um1-23","title":"Worg’s Eye Watch Post","before":"Raucous goblin voices carry through adjoining rooms.","after":"Raucous goblin voices carry through adjoining rooms.\n\nThe voices give the connected rooms a sense of occupation before you can see everyone inside them. You can stop to listen for words, decide whether to call out, or take a position that leaves the route behind you clear. The conversation need not begin with a drawn weapon."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","23"],"field":"read","id":"um1-24","title":"Halls of Hopelessness","before":"Old bones lie near an arch between two pillars. Another alcove holds a chained skeleton.","after":"Old bones lie near an arch between two pillars. Another alcove holds a chained skeleton.\n\nThe arch and the chained remains give you two distinct things to examine. Old bones lie loose near one feature and held in place near the other. You can study the surrounding stonework, inspect a fastening, or keep your distance while comparing what you see."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","24"],"field":"read","id":"um1-25","title":"Excavation Site","before":"Discarded tools lie beside a low, rough tunnel through rubble.","after":"Discarded tools lie beside a low, rough tunnel through rubble.\n\nThe tools remain at the mouth of work that changes from built stone to a rough opening through rubble. The low clearance is visible before you enter. You can check the unstable-looking ground, judge what equipment will fit, or leave a mark identifying the way back."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","25"],"field":"read","id":"um1-26","title":"Clean Tunnels","before":"Floating candles light a corridor strangely free of dust.","after":"Floating candles light a corridor strangely free of dust.\n\nThe floating lights make the lack of dust especially noticeable. You can compare this floor with the passages you have already crossed, watch a candle without reaching for it, or inspect the corridor one section at a time. The difference is visible; its cause is not yet established."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","26"],"field":"read","id":"um1-27","title":"Hidden Demiplane","before":"A harp-player relief looks down over a broken length of pole.","after":"A harp-player relief looks down over a broken length of pole.\n\nThe carved musician and the broken pole share the space without explaining one another. Your light follows the relief's edges and the jagged break in the wood. You can examine either object, listen in the chamber, or keep the visible approach watched while someone takes notes."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","27"],"field":"read","id":"um1-28","title":"Grick Snack Watch Post","before":"Scavenged bedding surrounds an eye-carved obelisk; frightened voices sound from beyond.","after":"Scavenged bedding surrounds an eye-carved obelisk; frightened voices sound from beyond.\n\nThe bedding shows everyday use around a monument whose carved eye is harder to ignore. The frightened voices come from beyond what you can plainly see. You can answer them, inspect the obelisk from a distance, or look for a position that allows the speakers room to approach."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","28"],"field":"read","id":"um1-29","title":"Eye See You","before":"Old shields line the tunnel as a floating eye appears ahead.","after":"Old shields line the tunnel as a floating eye appears ahead.\n\nThe shields line the way toward the hovering shape, giving you landmarks between yourself and it. The eye is visible, but its intention is not. You can stop, speak, study what it does, or keep the passage behind you available while choosing your next move."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","29"],"field":"read","id":"um1-30","title":"Mad Elemental","before":"A howling draft presses against the door. Beyond it, the passage bends sharply.","after":"A howling draft presses against the door. Beyond it, the passage bends sharply.\n\nThe draft carries sound around the turn, but the bend keeps the far stretch out of view. You can judge the doorway and the nearer floor before committing to the passage. The wind gives you something to listen to as well as something to push against."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","30"],"field":"read","id":"um1-31","title":"Delvers’ Hall","before":"Dusty dwarven statues stand in alcoves. Grooves cross the floor beside a shifted plinth.","after":"Dusty dwarven statues stand in alcoves. Grooves cross the floor beside a shifted plinth.\n\nThe grooves and shifted base make one part of the floor different from the rest. The statues stand in their alcoves while those marks cross the ground before them. You can follow the visible traces, inspect a plinth, or leave someone watching the hall."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","31"],"field":"read","id":"um1-32","title":"VIP Suite","before":"Carvings turn the walls into the likeness of a stone cavern.","after":"Carvings turn the walls into the likeness of a stone cavern.\n\nThe carved walls imitate natural stone closely enough to reward a second look. Tool-work and rock are part of the same view here. You can compare the surfaces, look for where one carved feature meets another, or follow the visible passage without disturbing anything."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","32"],"field":"read","id":"um1-33","title":"North Dormitory","before":"Eleven bare stone sleeping shelves line the walls.","after":"Eleven bare stone sleeping shelves line the walls.\n\nThe bare shelves offer places where sleepers once lay, but little personal clutter remains to tell you who they were. You can examine a particular recess or study the floor between them. The repeated stone shapes also give you a way to describe this room on your map."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","33"],"field":"read","id":"um1-34","title":"South Dormitory","before":"Stone beds line the room. One holds a web-covered skeleton.","after":"Stone beds line the room. One holds a web-covered skeleton.\n\nThe webbing connects the remains to the bed beneath them, making the untouched areas worth distinguishing from the paths between the stone frames. You can look closely without reaching in, keep watch over the room, or choose to leave the resting place undisturbed."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","34"],"field":"read","id":"um1-35","title":"Hall of Rats","before":"Squeaking carries through an ajar door. A large rat sleeps on a ruined throne.","after":"Squeaking carries through an ajar door. A large rat sleeps on a ruined throne.\n\nThe ajar door lets you listen before entering, while the ruined throne makes the sleeping rat easy to place within the room. You can keep your distance, inspect the visible floor, or consider how much noise an approach would make. The animal has not yet answered your presence."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","35"],"field":"read","id":"um1-36","title":"Lost Halls","before":"Rubble and broken statues crowd the halls. From a closed door comes muffled weeping.","after":"Rubble and broken statues crowd the halls. From a closed door comes muffled weeping.\n\nThe broken figures and fallen stone complicate a quick approach to the closed door. The weeping gives you a direction without a clear view of its source. You can call through the barrier, inspect the nearer ground, or decide who will listen while the others watch the hall."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","36"],"field":"read","id":"um1-37","title":"Map Room","before":"A towering cutaway of a deep dungeon covers the wall. Something moves at the bottom of an open pit.","after":"A towering cutaway of a deep dungeon covers the wall. Something moves at the bottom of an open pit.\n\nThe wall drawing gives you something enormous to study, while the pit demands attention to where you put your feet. Movement below is only partly visible from its edge. You can remain back, examine the cutaway, or choose a careful place from which to look down."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","37"],"field":"read","id":"um1-38","title":"Secret Tunnel","before":"Footprints mark the dust in a curving passage.","after":"Footprints mark the dust in a curving passage.\n\nThe prints offer a trail to inspect rather than a person already in view. The curve hides the next stretch of passage, leaving the near dust as your clearest evidence. You can compare the marks, listen around the bend, or record where you first saw them."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","38"],"field":"read","id":"um1-39","title":"Big Ears Watch Post","before":"A two-headed stone king stands beside a column. Squabbling voices carry from the north.","after":"A two-headed stone king stands beside a column. Squabbling voices carry from the north.\n\nThe king's two faces look over the same chamber while the quarrel reaches you from the north. The column interrupts part of that view. You can study the stone figure, listen for the speakers' words, or decide where to stand before drawing their attention."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","39"],"field":"read","id":"um1-40","title":"Fearful Mimicry","before":"Three tall elven warrior statues hold spears. One weapon gleams gold.","after":"Three tall elven warrior statues hold spears. One weapon gleams gold.\n\nThe spears make a repeated pattern until the gleaming weapon breaks it. The statues' height lets you study some details more easily than others. You can compare the three figures from the floor, inspect the surrounding space, or decide how closely to approach the unusual spear."},{"global":"ECHO_WATERDEEP_DATA","path":["rooms","40"],"field":"read","id":"um1-41","title":"Cracked Ceiling","before":"Rubble lies beneath a deep ceiling fissure. Old mining tools sit in stone wheelbarrows.","after":"Rubble lies beneath a deep ceiling fissure. Old mining tools sit in stone wheelbarrows.\n\nThe fissure gives your light a dark line to follow overhead, while the wheelbarrows keep the room's former work close at hand. You can inspect the debris, examine a tool, or look up before crossing beneath the damaged ceiling. The room offers questions at more than one height."},{"global":"ECHO_WATERDEEP_DATA","path":["arrival","0"],"field":"read","id":"wd-arrival","title":"Waterdeep arrival","before":"The road gives way to streets that seem to have no end. Bells sound somewhere above the rooftops; below them, carts, voices and footsteps press onward. For the first time in days, the question is not where you can go, but where you want to belong.","after":"The road gives way to streets that seem to have no end. Bells sound somewhere above the rooftops; below them, carts, voices and footsteps press onward. For the first time in days, the question is not where you can go, but where you want to belong.\n\nThe press of the streets gives you practical choices immediately: where to keep together, where to stop, and whom to ask for directions. Bells and calls overlap above the rolling carts. There is time to choose your first destination rather than let the crowd choose it for you."},{"global":"ECHO_WATERDEEP_DATA","path":["arrival","1"],"field":"read","id":"wd-dracuseth","title":"Dracuseth at the Portal","before":"Dracuseth rises from a table near the wall. “There you are. Sit down. Tell me what happened before anyone tells you what it means.”","after":"Dracuseth rises from a table near the wall. “There you are. Sit down. Tell me what happened before anyone tells you what it means.”\n\nThe offered seats give the conversation somewhere to begin without turning it into a formal report. You can set down what you choose to share and keep the rest close. Dracuseth waits for your account, leaving the first questions and the pace of the meeting to you."},{"global":"ECHO_WATERDEEP_DATA","path":["arrival","2"],"field":"read","id":"wd-portal","title":"The Yawning Portal","before":"Conversation rolls around the great well like water around a rock. A rope creaks. Someone at the next table stops talking to listen.","after":"Conversation rolls around the great well like water around a rock. A rope creaks. Someone at the next table stops talking to listen.\n\nThe well draws a circle of attention through the room, with ordinary conversation continuing around it. The creak of the rope gives you a reminder of the space below. You can find a table, ask about the descent, or watch how others approach the opening."},{"global":"ECHO_WATERDEEP_DATA","path":["arrival","3"],"field":"read","id":"wd-research","title":"Second Margin research visit","before":"Three trays sit on the desk: observations, interpretations, and unanswered questions. Selise places a clean sheet in front of you. “Start with what someone else could check.”","after":"Three trays sit on the desk: observations, interpretations, and unanswered questions. Selise places a clean sheet in front of you. “Start with what someone else could check.”\n\nThe separate trays give every page a place without requiring you to settle its meaning first. You can offer an observation, ask how it could be checked, or keep a detail private. The clean sheet leaves room to write down a question before anyone chooses an answer."},{"global":"ECHO_WATERDEEP_DATA","path":["arrival","4"],"field":"read","id":"wd-workshop","title":"Ninepin Works: safe comparison","before":"Ceramic dishes sit between brass instruments. Orren turns a tool around so you can see its edge. “Nothing cut, crushed, or heated unless you agree.”","after":"Ceramic dishes sit between brass instruments. Orren turns a tool around so you can see its edge. “Nothing cut, crushed, or heated unless you agree.”\n\nThe dishes and instruments are within sight, but the tool is presented for your inspection rather than pressed into use. You can ask what each part does and which test it permits. Your belongings remain yours to keep untouched until you agree otherwise."},{"global":"ECHO_WATERDEEP_DATA","path":["arrival","5"],"field":"read","id":"wd-factions","title":"Offers with strings attached","before":"A folded note rests beside your cup. It asks for a conversation, and makes no claim that you owe one.","after":"A folded note rests beside your cup. It asks for a conversation, and makes no claim that you owe one.\n\nThe folded paper offers a proposal you can inspect without committing to it. You can read the request, ask who delivered it, or leave it beside the cup for later. A meeting can be accepted, postponed, or refused before any wider obligation is discussed."},{"global":"ECHO_WATERDEEP_DATA","path":["arrival","6"],"field":"read","id":"wd-brief","title":"First descent briefing","before":"A blank route sheet lies beside a coil of rope. Durnan taps the empty line at the bottom. “That is for the way back.”","after":"A blank route sheet lies beside a coil of rope. Durnan taps the empty line at the bottom. “That is for the way back.”\n\nThe rope and the route sheet suggest two different sorts of preparation: what will help you descend and what will help someone understand your return. You can discuss a stopping point, check the equipment, or ask what information is expected before taking the first step."},{"global":"ECHO_WATERDEEP_DATA","path":["arrival","7"],"field":"read","id":"wd-return","title":"Waterdeep debrief","before":"The noise of the city returns before the familiar doorway comes into view. The empty line on your route sheet is no longer empty.","after":"The noise of the city returns before the familiar doorway comes into view. The empty line on your route sheet is no longer empty.\n\nThe familiar entrance offers a place to pause before your account becomes someone else's retelling. You can decide what to carry inside, what needs care, and what should be recorded first. The city's ordinary noise continues around the discoveries you brought back."},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","0","beats","0"],"field":"read","id":"arc-map-offer","title":"Ilvara draws a small box","before":["Ilvara places a clean sheet beside your cups and draws a small rectangle. “This is the part I am paying for. Mark where you went, where you stopped, and what made you stop. A warning that brings someone home is a useful map.”"],"after":["Ilvara places a clean sheet beside your cups and draws a small rectangle. “This is the part I am paying for. Mark where you went, where you stopped, and what made you stop. A warning that brings someone home is a useful map.”","The rectangle leaves most of the paper empty. Beside the cups, Ilvara's clean sheet offers room for turns, blocked passages, and the point where your light or courage ran short. She waits for your questions before the first route is agreed."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","0","beats","1"],"field":"read","id":"arc-map-well","title":"Entrywell: leave a route home","before":["Your boots settle into a thin bed of sand. Battered shields hang around the stone chamber. The passage ahead turns out of sight; above you, the tavern is already a distant circle of noise."],"after":["Your boots settle into a thin bed of sand. Battered shields hang around the stone chamber. The passage ahead turns out of sight; above you, the tavern is already a distant circle of noise.","The sand gives you a surface on which to notice fresh tracks or leave a deliberate mark. The hanging shields frame the chamber, but the bend hides the next stretch. The circle overhead remains the clearest landmark for the way back."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","0","beats","2"],"field":"read","id":"arc-map-junction","title":"Pillar junction: decide what to follow","before":["Demon reliefs line the broad passage. Shallow steps descend to a forest of pillars, where the light breaks into separate pools. Scratched words point toward the southern exit: “Certain death this way.”"],"after":["Demon reliefs line the broad passage. Shallow steps descend to a forest of pillars, where the light breaks into separate pools. Scratched words point toward the southern exit: “Certain death this way.”","The pillars divide sight into narrow lanes, and the steps change the height of the floor beneath your feet. The scratched warning is easy to read; whether it deserves belief is another matter. You can examine each visible exit before choosing one."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","0","beats","3"],"field":"read","id":"arc-map-threshold","title":"The Undertakers’ price","before":["Three stone nobles overlook a hall strewn with old bones. Someone steps into the lamplight in elaborate dark clothes. “Visitors,” the figure says, with a smile held a little too long. “Ten gold each, and you may continue.”"],"after":["Three stone nobles overlook a hall strewn with old bones. Someone steps into the lamplight in elaborate dark clothes. “Visitors,” the figure says, with a smile held a little too long. “Ten gold each, and you may continue.”","Old bones lie below the carved nobles, while the speaker's clothes and measured smile hold your attention. There is a demand on the table, but no agreement yet. The space between you leaves time to ask who collects this toll and what it buys."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","0","beats","4"],"field":"read","id":"arc-map-detours","title":"If they investigate a side branch","before":["Your route can end here with a blank edge, or you can spend more of your light learning what lies beyond it."],"after":["Your route can end here with a blank edge, or you can spend more of your light learning what lies beyond it.","The blank edge marks the boundary of what you have checked. Beyond it, a passage can be investigated or left honestly unfinished. You can compare the light and supplies still in hand with the route you already know before choosing to continue."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","0","beats","5"],"field":"read","id":"arc-map-withdraw","title":"Close the first survey","before":["The marks you made on the way in now point toward home. Behind you lie measured passages, unanswered questions, and at least one reason to come back better prepared."],"after":["The marks you made on the way in now point toward home. Behind you lie measured passages, unanswered questions, and at least one reason to come back better prepared.","A turn that was unfamiliar on the descent now has a place in your account. Your marks give you something concrete to check as you retrace the route. The unanswered branches remain where you left them, without requiring an answer tonight."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","1","beats","0"],"field":"read","id":"arc-instrument-offer","title":"Orren’s description","before":["Orren sets a drawing of a brass instrument on the bench. One foot in the drawing has a small, uneven notch. “That mark is mine. I can make another tool. What I cannot replace is an honest account of what happened to this one.”"],"after":["Orren sets a drawing of a brass instrument on the bench. One foot in the drawing has a small, uneven notch. “That mark is mine. I can make another tool. What I cannot replace is an honest account of what happened to this one.”","The notch is small enough to overlook until Orren points it out. His drawing records a particular tool rather than a chest of interchangeable brass. You can ask what condition matters, what handling is permitted, and how he would recognize an altered instrument."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","1","beats","1"],"field":"read","id":"arc-instrument-rival","title":"An offer from the Gilded Compass","before":["Kestrel places her closed notebook on the table without sliding it toward you. “We can compare what each of us is willing to share. Routes have names attached to them. So should the people who do the measuring.”"],"after":["Kestrel places her closed notebook on the table without sliding it toward you. “We can compare what each of us is willing to share. Routes have names attached to them. So should the people who do the measuring.”","The notebook stays closed between the cups. Kestrel offers a conversation, not unrestricted access to her crew's work. You can name a route or question you would exchange before deciding whether either side should open its records."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","1","beats","2"],"field":"read","id":"arc-instrument-reentry","title":"Use the route you earned","before":["The first mark is still where you left it, if the passage has remained undisturbed. Ahead, the junction opens toward the branch your last survey left unfinished."],"after":["The first mark is still where you left it, if the passage has remained undisturbed. Ahead, the junction opens toward the branch your last survey left unfinished.","Your earlier survey gives the junction a shape you can recognize, but it cannot promise that every passage has stayed the same. Check the marks and visible approaches against that account. The unfinished branch remains a choice rather than an obligation."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","1","beats","3"],"field":"read","id":"arc-instrument-excavation","title":"The tool pile at 25a","before":["Three picks and two shovels lie across rough stone at the mouth of a low tunnel. Rubble crowds the floor. The passage beyond is barely high enough to crawl through without bowing your head."],"after":["Three picks and two shovels lie across rough stone at the mouth of a low tunnel. Rubble crowds the floor. The passage beyond is barely high enough to crawl through without bowing your head.","The tools mark a working entrance, and loose rubble narrows the space available for movement. The low roof would make passing another traveler awkward. You can look for signs of recent work and consider how to withdraw before entering the crawl."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","1","beats","4"],"field":"read","id":"arc-instrument-negotiation","title":"Two claims, one instrument","before":["The case lies between the people who want it. For a moment, the dungeon is quiet enough to hear the little plumb bob tap against its brass frame."],"after":["The case lies between the people who want it. For a moment, the dungeon is quiet enough to hear the little plumb bob tap against its brass frame.","The light catches the frame each time the little weight swings. Whoever opens the case will be handling the very thing under discussion. Names, ownership, and permission can be settled here before a tool changes hands."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","1","beats","5"],"field":"read","id":"arc-instrument-detour","title":"At the edge of the prepared route","before":["Beyond the low tunnel, another hall continues past the place you came to find. The instrument does not require you to follow it."],"after":["Beyond the low tunnel, another hall continues past the place you came to find. The instrument does not require you to follow it.","The continuing hall offers a new question beyond the object you came for. Your known route still matters, and carrying a case may change how easily you travel it. There is time to mark the unexplored direction and leave it for another expedition."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","1","beats","6"],"field":"read","id":"arc-instrument-delivery","title":"A bench test, not a revelation","before":["Orren clears a place on the bench before anyone opens the case. “Tell me who handled it, what changed, and what you want left untouched. Then we can find out whether it still measures straight.”"],"after":["Orren clears a place on the bench before anyone opens the case. “Tell me who handled it, what changed, and what you want left untouched. Then we can find out whether it still measures straight.”","The cleared bench makes room for the case without burying it among ordinary work. Orren waits for your account before reaching inside. The notch, frame, and moving weight can then be compared with the drawing you took below."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","2","beats","0"],"field":"read","id":"arc-passage-brief","title":"Who can actually promise passage?","before":["Ilvara lays two sheets over the map. “One for the route. One for the promises. I would like the second to be as accurate as the first.”"],"after":["Ilvara lays two sheets over the map. “One for the route. One for the promises. I would like the second to be as accurate as the first.”","A line on one page can name a corridor; a line on the other can say who expects to use it. Ilvara keeps both sheets visible. You can decide whose agreement is still missing and what would make a promised passage unsafe."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","2","beats","1"],"field":"read","id":"arc-passage-undertakers","title":"A northern agreement, with limits","before":["The speaker studies the narrow line you have drawn on the map. “You want to pass. I want to know when strangers are walking behind me. There may be a version of this conversation we both survive.”"],"after":["The speaker studies the narrow line you have drawn on the map. “You want to pass. I want to know when strangers are walking behind me. There may be a version of this conversation we both survive.”","The drawn route ends where knowledge ends, leaving the speaker room to point out a concern without granting everything you ask. Weapons remain visible during the conversation. You can offer notice, limits, or a different route before either side calls the matter settled."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","2","beats","2"],"field":"read","id":"arc-passage-guild-contact","title":"The offer that cannot be taken on trust","before":["The answer comes after a long look at your weapons. “The large stitched creature is a problem. Remove it, and perhaps your little journeys will stop being ours.”"],"after":["The answer comes after a long look at your weapons. “The large stitched creature is a problem. Remove it, and perhaps your little journeys will stop being ours.”","The stitched creature becomes the price of a possible arrangement, not proof that one already exists. The speaker watches for your answer. You can ask which route is being discussed, what removing the threat means, and who will honor the terms afterward."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","2","beats","3"],"field":"read","id":"arc-passage-worg-approach","title":"Optional visit to Worg’s Eye","before":["Old masonry gives way to the rough excavation you have already measured. Farther on, the route bends toward voices. There is still time to announce yourselves from a distance."],"after":["Old masonry gives way to the rough excavation you have already measured. Farther on, the route bends toward voices. There is still time to announce yourselves from a distance.","The change from masonry to excavation gives you a recognizable point on the route. Voices carry around the bend without revealing everyone beyond it. Calling out here would announce your approach while leaving distance between the conversation and your weapons."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","2","beats","4"],"field":"read","id":"arc-passage-trial","title":"Test only the promise you made","before":["You reach the point named in the agreement. The map tells you where you are. The next few moments will tell you whether the promise reaches this far."],"after":["You reach the point named in the agreement. The map tells you where you are. The next few moments will tell you whether the promise reaches this far.","The agreed landmark gives both sides a place to test the terms. Reaching it proves the route can be followed; it does not reveal what waits farther on. You can pause here, announce yourselves, and compare the response with the words actually exchanged."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","2","beats","5"],"field":"read","id":"arc-passage-note","title":"Optional: a courteous observer","before":["A small folded note rests where the light catches it. The paper is dry. The handwriting is unhurried."],"after":["A small folded note rests where the light catches it. The paper is dry. The handwriting is unhurried.","There is no need to name the writer before examining the words. The dry fold and steady hand are visible details you can record. You may read, copy, leave, or secure the note without accepting any invitation it contains."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_DATA","path":["packages","2","beats","6"],"field":"read","id":"arc-passage-report","title":"Put the limits on the map","before":["Ilvara reads the route once and the promises twice. Then she leaves a clear blank below the final line. “What would make this stop being true?”"],"after":["Ilvara reads the route once and the promises twice. Then she leaves a clear blank below the final line. “What would make this stop being true?”","The blank under the final line leaves space for limits, warning signs, and names that still need an answer. Ilvara has not turned the account into a permanent guarantee. You can describe what you checked and what a later traveler must check again."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_CAST","path":["rivals","0"],"field":"say","id":"kestrel","title":"Captain of the Gilded Compass","before":["“Exchange a measured stretch for a measured stretch. We keep each other’s names on the copies.”","“An empty space on a map is an honest answer. Tell me what stopped you.”","“If the bargain needs one of us dead to count as success, someone wrote a bad bargain.”"],"after":["“Exchange a measured stretch for a measured stretch. We keep each other’s names on the copies.”","“An empty space on a map is an honest answer. Tell me what stopped you.”","“If the bargain needs one of us dead to count as success, someone wrote a bad bargain.”"]},{"global":"ECHO_UNDERMOUNTAIN_ARC_CAST","path":["rivals","1"],"field":"say","id":"pell","title":"Gilded Compass scout and route keeper","before":["“Show me the landmark that still works when the lamp goes out.”","“I stopped there. Everything beyond that mark is somebody else’s story.”","“We can come back with more rope. That is what the rope is for.”"],"after":["“Show me the landmark that still works when the lamp goes out.”","“I stopped there. Everything beyond that mark is somebody else’s story.”","“We can come back with more rope. That is what the rope is for.”"]},{"global":"ECHO_UNDERMOUNTAIN_ARC_CAST","path":["rivals","2"],"field":"say","id":"nym","title":"Gilded Compass cataloger and wizard","before":["“The scratch is new. That gives us an order of events, not a culprit.”","“May I make a drawing before anyone decides what to do with it?”","“A familiar mark deserves a comparison. It does not deserve a story invented around it.”"],"after":["“The scratch is new. That gives us an order of events, not a culprit.”","“May I make a drawing before anyone decides what to do with it?”","“A familiar mark deserves a comparison. It does not deserve a story invented around it.”"]},{"global":"ECHO_UNDERMOUNTAIN_ARC_CAST","path":["returns","0"],"field":"read","id":"arc-map-return","title":"Home with an honest map","before":["The court is doing ordinary work when you return: a shutter creaks, a bucket rests beside the well, and Orenna is shifting a parcel away from the stair. She looks up and counts the faces she recognizes. “Back, then. Set the wet things where they can dry. Tell me what needs keeping.”"],"after":["The court is doing ordinary work when you return: a shutter creaks, a bucket rests beside the well, and Orenna is shifting a parcel away from the stair. She looks up and counts the faces she recognizes. “Back, then. Set the wet things where they can dry. Tell me what needs keeping.”","The well, stair, and drying space give the return its familiar shape. Orenna makes practical room without deciding what your expedition means. You can set down wet equipment before choosing which news belongs at a shared table."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_CAST","path":["returns","1"],"field":"read","id":"arc-instrument-return","title":"What the instrument can tell you","before":["A familiar chair has been left clear of the evening’s baskets. Nessa closes the book she was working on and makes room without reaching for your equipment. “Something to repair,” she asks, “or something you want left exactly as it is?”"],"after":["A familiar chair has been left clear of the evening’s baskets. Nessa closes the book she was working on and makes room without reaching for your equipment. “Something to repair,” she asks, “or something you want left exactly as it is?”","The cleared chair offers somewhere to rest without spreading a delicate instrument across unfinished household work. Nessa's question leaves its handling to you. A repair can be requested, or the object can remain untouched while its story is recorded."]},{"global":"ECHO_UNDERMOUNTAIN_ARC_CAST","path":["returns","2"],"field":"read","id":"arc-passage-return","title":"The route and the people at home","before":["There is an argument in the court about where a long basket should stand. It is a small, familiar argument: somebody needs the stair, somebody needs the basket, and supper will be late if neither of them moves. Then someone notices you at the gate and pulls another chair toward the table."],"after":["There is an argument in the court about where a long basket should stand. It is a small, familiar argument: somebody needs the stair, somebody needs the basket, and supper will be late if neither of them moves. Then someone notices you at the gate and pulls another chair toward the table.","The basket still needs moving whether the dungeon's promises held or failed. The extra chair opens a place in that ordinary evening. You can join the discussion, ask for quiet, or keep your account for a more private conversation."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","0","options","1"],"field":"read","id":"gundren","title":"","before":["Gundren’s rescue is part of the account you can now give. His next steps depend on where he is, what he needs, and what he has actually learned."],"after":["Gundren’s rescue is part of the account you can now give. His next steps depend on where he is, what he needs, and what he has actually learned.","There is room in that account for his own words. A rescue can be named plainly without speaking for every decision that follows it. You can ask what he wants carried in the next message and what should stay between those present."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","0","options","2"],"field":"read","id":"gundren","title":"","before":["A space has been left at the table. No one has decided what to say about it."],"after":["A space has been left at the table. No one has decided what to say about it.","The empty place gives the conversation a boundary: someone remains unaccounted for. You can put the last reliable sighting beside the unanswered questions, leaving guesses separate from anything a searcher could use."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","0","options","3"],"field":"read","id":"gundren","title":"","before":["The first question is not about treasure. It is who should be told, and who should hear the news in person."],"after":["The first question is not about treasure. It is who should be told, and who should hear the news in person.","News travels differently when a name belongs to someone a listener loved. You can decide who should speak, what has been confirmed, and what practical help can be offered. No account of the mine needs to crowd out that first conversation."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","0","options","4"],"field":"read","id":"gundren","title":"","before":["A reliable address would make the next message possible. Until then, news and intended recipients remain separate questions."],"after":["A reliable address would make the next message possible. Until then, news and intended recipients remain separate questions.","The message can be written while its destination remains open. A name and a known address are useful things to separate from rumor. You can keep a copy ready without pretending it has already reached him."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","1","options","1"],"field":"read","id":"nundro","title":"","before":["Nundro’s rescue can be reported without deciding his next journey for him. There is still room to ask what care he needs and whom he wants told."],"after":["Nundro’s rescue can be reported without deciding his next journey for him. There is still room to ask what care he needs and whom he wants told.","His account need not begin with the mine's value. There is time to hear what he remembers and what he would rather leave unsaid. You can offer assistance without deciding where he must live or whom he must trust."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","1","options","2"],"field":"read","id":"nundro","title":"","before":["Nundro’s last known situation remains an unfinished part of the account. What would establish where he is now?"],"after":["Nundro’s last known situation remains an unfinished part of the account. What would establish where he is now?","The record has a gap where a present address should be. A witnessed departure, a reliable message, or a fresh sighting could change that. Until then, the question remains open rather than becoming a convenient ending."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","1","options","3"],"field":"read","id":"nundro","title":"","before":["A quiet place is made for the news. For a while, no one asks what the expedition earned."],"after":["A quiet place is made for the news. For a while, no one asks what the expedition earned.","The quiet leaves space for a name and the people who should hear it. You can choose what to say of the loss and what remains uncertain. Practical arrangements can follow without asking grief to finish first."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","1","options","4"],"field":"read","id":"nundro","title":"","before":["There is a message to send before there is a celebration to arrange."],"after":["There is a message to send before there is a celebration to arrange.","Words on a page can carry relief without promising a reunion already arranged. You can ask which address to use and what details belong in the message. The next journey remains his choice as well as yours."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","2","options","1"],"field":"read","id":"nezznar","title":"","before":["Nezznar’s death settles his fate. It does not settle which parts of his work remain."],"after":["Nezznar’s death settles his fate. It does not settle which parts of his work remain.","His surviving papers, agreements, and unanswered questions must be judged on their own evidence. You can name the end of his life without calling every threat ended. What needs checking before anyone treats his work as abandoned?"]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","2","options","2"],"field":"read","id":"nezznar","title":"","before":["Custody leaves practical questions: where is Nezznar held, who has accepted responsibility, and what must be arranged before you leave?"],"after":["Custody leaves practical questions: where is Nezznar held, who has accepted responsibility, and what must be arranged before you leave?","The account needs names as well as intentions. A keeper, an agreed place, and a clear handover would make responsibility visible. You can decide what questions may be asked before departure without granting the prisoner freedom by implication."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","2","options","3"],"field":"read","id":"nezznar","title":"","before":["His last verified movement matters more than a guess about his destination. What did you actually see?"],"after":["His last verified movement matters more than a guess about his destination. What did you actually see?","An escape leaves a last place and time that can be recorded honestly. Beyond that point, a trail requires new evidence. You can share a warning without giving a guess the weight of a witnessed destination."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","2","options","4"],"field":"read","id":"nezznar","title":"","before":["The terms still matter. Which promises were made, which have been kept, and what remains uncertain?"],"after":["The terms still matter. Which promises were made, which have been kept, and what remains uncertain?","The original words and the next obligation can be read together. You can ask who has authority to speak for each side and how a breach would be recognized. Agreement on one matter need not settle every other dispute."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","2","options","5"],"field":"read","id":"nezznar","title":"","before":["No one calls the road clear. The question is what can be done safely with the information you have."],"after":["No one calls the road clear. The question is what can be done safely with the information you have.","The unfinished danger belongs in the account beside what has already been achieved. You can choose a cautious next step, seek help, or delay. None of those choices requires calling an unresolved enemy defeated."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","3","options","1"],"field":"read","id":"mine","title":"","before":["A route used by adventurers will be asked to carry other lives. Which passages have actually been assessed for that work?"],"after":["A route used by adventurers will be asked to carry other lives. Which passages have actually been assessed for that work?","The return route and the places still unexamined matter to workers as much as to explorers. You can mark each honestly before inviting anyone inside. A claim to the mine does not measure the strength of its supports or the safety of its water."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","3","options","2"],"field":"read","id":"mine","title":"","before":["The known passages and unanswered questions belong in the same account. Neither should be mistaken for the other."],"after":["The known passages and unanswered questions belong in the same account. Neither should be mistaken for the other.","A checked passage can be drawn with confidence while its neighboring room stays a question. That distinction gives the next visitor useful guidance. You can decide what further survey or help is needed before calling the whole place safe."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","3","options","3"],"field":"read","id":"mine","title":"","before":["Control of the mine is still disputed. A route, a claim and permission to use it are three different things to establish."],"after":["Control of the mine is still disputed. A route, a claim and permission to use it are three different things to establish.","The account can name who is present, who makes each claim, and what was actually agreed. Those details offer a beginning for negotiation. They do not require everyone to accept the same owner before the next conversation."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","3","options","4"],"field":"read","id":"mine","title":"","before":["Restricted access leaves a question for anyone who comes after you: what is the danger, and who can decide when it is safe to enter?"],"after":["Restricted access leaves a question for anyone who comes after you: what is the danger, and who can decide when it is safe to enter?","A warning is most useful when it describes a particular hazard and a way to avoid it. You can record the boundary, the reason for it, and the person who should be consulted. Closing a route need not erase the discoveries beyond it."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","3","options","5"],"field":"read","id":"mine","title":"","before":["The mine can no longer be used as it was. The next account must distinguish what was lost from what can still be recovered."],"after":["The mine can no longer be used as it was. The next account must distinguish what was lost from what can still be recovered.","The loss needs its own careful inventory before any rebuilding is promised. You can separate inaccessible places, damaged equipment, and things witnessed destroyed. What remains recoverable is a question for evidence rather than optimism."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","4","options","1"],"field":"read","id":"prisoners","title":"","before":["Each confirmed return has its own name, destination and next need. Review them one at a time."],"after":["Each confirmed return has its own name, destination and next need. Review them one at a time.","A shared heading cannot tell every person's story. You can ask what each survivor wants carried home, which names may be shared, and what help is still needed. Their rescue need not become permission to speak for them."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","4","options","2"],"field":"read","id":"prisoners","title":"","before":["Safe travel requires more than choosing a destination. Who has agreed to accompany each person who still needs help?"],"after":["Safe travel requires more than choosing a destination. Who has agreed to accompany each person who still needs help?","The route, companion, and stopping place can be checked together. A promise to help matters most when someone knows what it requires. You can arrange the next step without describing an escort that has not yet happened."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","4","options","3"],"field":"read","id":"prisoners","title":"","before":["The names still missing are copied onto a separate page, where they cannot disappear among completed errands."],"after":["The names still missing are copied onto a separate page, where they cannot disappear among completed errands.","That separate page keeps the unfinished search visible. Beside each name, there is room for a last sighting and a question someone can pursue. Rumors can be preserved without being mistaken for answers."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","4","options","4"],"field":"read","id":"prisoners","title":"","before":["The list is checked a final time. No one adds another name."],"after":["The list is checked a final time. No one adds another name.","A completed list deserves a clear boundary. You can retain the names already checked and the evidence behind them, without manufacturing another rescue to fill the silence. The next task can begin from what was truly established."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","5","options","1"],"field":"read","id":"promises","title":"","before":["There are still promises that need an answer. What should their recipients know before the party leaves?"],"after":["There are still promises that need an answer. What should their recipients know before the party leaves?","The original words give each obligation a shape. You can name its recipient, its limit, and the next honest answer you can send. Choosing another road need not mean leaving someone to guess whether you will return."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","5","options","2"],"field":"read","id":"promises","title":"","before":["Receipts and returned messages make a small, untidy pile. There is room on the table for another map."],"after":["Receipts and returned messages make a small, untidy pile. There is room on the table for another map.","The papers mark particular errands answered rather than every debt forgotten. You can keep those confirmations together and leave room for any later question. A new map can be opened without losing the record beneath it."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","5","options","3"],"field":"read","id":"promises","title":"","before":["The accepted changes to the promise belong beside its original terms. What was agreed, and when should it be reviewed?"],"after":["The accepted changes to the promise belong beside its original terms. What was agreed, and when should it be reviewed?","The changed terms need the same care as the first bargain. You can record who accepted them and what still has to happen. A later reader should be able to follow the agreement without having heard this conversation."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","6","options","1"],"field":"read","id":"custody","title":"","before":["Blank labels lie beside the packs. There is space for a name, an owner, and a line saying what may be done with what is inside."],"after":["Blank labels lie beside the packs. There is space for a name, an owner, and a line saying what may be done with what is inside.","Each label can travel with an object rather than relying on whoever remembers the story. You can decide what may be opened, copied, or shown. An owner's silence need not become permission for the next curious hand."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","6","options","2"],"field":"read","id":"custody","title":"","before":["Permission has boundaries: which part may be copied, who may see it, and what remains with its owner?"],"after":["Permission has boundaries: which part may be copied, who may see it, and what remains with its owner?","A permitted copy can carry a clear note about its use. You can name its intended readers and keep withheld details separate. Sharing one observation need not surrender everything that led to it."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","6","options","3"],"field":"read","id":"custody","title":"","before":["The receipt names where the object is, and leaves room for a second signature when it changes hands."],"after":["The receipt names where the object is, and leaves room for a second signature when it changes hands.","A signature can record a handover when it happens. Until then, the named location and keeper remain the last established account. You can arrange inspection without describing the object as already delivered elsewhere."]},{"global":"ECHO_TRANSITION_DATA","path":["outcomes","6","options","4"],"field":"read","id":"custody","title":"","before":["Two accounts describe the same object in different hands. The next useful question is when anyone last saw it."],"after":["Two accounts describe the same object in different hands. The next useful question is when anyone last saw it.","The disagreement can remain on the page while you seek a witnessed answer. Dates, receipts, and people who handled the object may narrow it. There is no need to settle ownership by choosing the tidier story."]},{"global":"ECHO_TRANSITION_DATA","path":["leads","0"],"field":"read","id":"research","title":"A second opinion at the Second Margin","before":["“Send the observation first,” reads the proposed inquiry. “What happened, who saw it, and what you are willing to have examined. We can discuss explanations afterward.”"],"after":["“Send the observation first,” reads the proposed inquiry. “What happened, who saw it, and what you are willing to have examined. We can discuss explanations afterward.”","The inquiry leaves space for a sketch, a date, and the name of a willing witness. Its request is narrow enough to answer without sending everything you possess. You can decide which observation deserves a second pair of eyes."]},{"global":"ECHO_TRANSITION_DATA","path":["leads","1"],"field":"read","id":"work","title":"Paid route work through the Yawning Portal","before":["“A clear account of where you stopped is worth more to me than a brave story with the dangerous part left out.”"],"after":["“A clear account of where you stopped is worth more to me than a brave story with the dangerous part left out.”","The offer values a usable warning as much as a completed route. You can ask what ground must be surveyed and where the commission ends. A map with an honest blank may be worth carrying home."]},{"global":"ECHO_TRANSITION_DATA","path":["leads","2"],"field":"read","id":"makers","title":"A craft question for Ninepin Works","before":["“A good mark tells you where to begin looking. It is not a whole history pressed into metal.”"],"after":["“A good mark tells you where to begin looking. It is not a whole history pressed into metal.”","The mark is a beginning for comparison: its shape, wear, and place on the tool can be recorded. A maker might recognize a habit that a stranger cannot. You can choose whether to send a drawing before undertaking a journey."]},{"global":"ECHO_TRANSITION_DATA","path":["leads","3"],"field":"read","id":"contact","title":"An address and an ordinary beginning","before":["“Come if the city has something you want. I can help you find a door and someone worth speaking to. The rest should be your decision.”"],"after":["“Come if the city has something you want. I can help you find a door and someone worth speaking to. The rest should be your decision.”","An offered introduction can open a conversation without committing you to the city. There is time to ask who is waiting and what help they can actually give. You can carry the address as an option while finishing work closer to home."]},{"global":"ECHO_TRANSITION_DATA","path":["beats","1"],"field":"read","id":"tr-homecoming","title":"Phandalin homecoming · the account before the celebration","before":["The familiar roofs appear beyond the fields. A worker rests both hands on a fence and watches your approach. By the time you reach the first houses, the question has traveled ahead of you: what news have you brought?"],"after":["The familiar roofs appear beyond the fields. A worker rests both hands on a fence and watches your approach. By the time you reach the first houses, the question has traveled ahead of you: what news have you brought?","The houses are familiar; the news you carry is not. There is space to pause before answering the first question. You can choose whose names should be spoken here and which matters deserve a quieter room."]},{"global":"ECHO_TRANSITION_DATA","path":["beats","2"],"field":"read","id":"tr-obligations","title":"Around the table · people, promises and custody","before":["A cleared table fills with the things a journey leaves behind: a folded message, a borrowed tool, a list of names. Outside, ordinary work continues. Here, you have time to decide what must happen before another road is taken."],"after":["A cleared table fills with the things a journey leaves behind: a folded message, a borrowed tool, a list of names. Outside, ordinary work continues. Here, you have time to decide what must happen before another road is taken.","Each object on the table points toward someone who may still be waiting. The tool can be returned, the message answered, and the list checked against your own account. None of those tasks has to be buried beneath a new destination."]},{"global":"ECHO_TRANSITION_DATA","path":["beats","3"],"field":"read","id":"tr-leads","title":"A reason to go · choose the city’s first two doors","before":["There are several ways to begin another journey: a question on a clean page, work that needs doing, or the address of someone willing to meet you. None of them tells you what you must leave behind."],"after":["There are several ways to begin another journey: a question on a clean page, work that needs doing, or the address of someone willing to meet you. None of them tells you what you must leave behind.","The page holds possible beginnings rather than a single command. You can compare what each journey asks of your time and whose help it needs. There is also room to write a reason to stay."]},{"global":"ECHO_TRANSITION_DATA","path":["beats","4"],"field":"read","id":"tr-delay","title":"If they stay · a useful day in Phandalin","before":["Morning starts with familiar sounds: a cartwheel in a rut, a door being unlatched, somebody calling across the street. There is work here that will still matter after the next great adventure has a name."],"after":["Morning starts with familiar sounds: a cartwheel in a rut, a door being unlatched, somebody calling across the street. There is work here that will still matter after the next great adventure has a name.","The unlatched doors and calls across the street make the town easy to recognize without making it finished. A delayed departure can leave space for a visit, an answer, or a repair. What would you choose to put in order today?"]},{"global":"ECHO_TRANSITION_DATA","path":["beats","5"],"field":"read","id":"tr-departure","title":"Departure · an agreed road and a way back","before":["At the edge of town, the road looks ordinary again. Packs settle, straps tighten, and the first turn waits for a choice. Behind you are people who know your names. Ahead is a city where introductions still matter."],"after":["At the edge of town, the road looks ordinary again. Packs settle, straps tighten, and the first turn waits for a choice. Behind you are people who know your names. Ahead is a city where introductions still matter.","The last familiar roofs offer a final point from which to check your direction. You can name a meeting place and the first planned stop before the road separates you from the town. A departure leaves room for messages to follow."]},{"global":"ECHO_TRANSITION_DATA","path":["beats","6"],"field":"read","id":"tr-road","title":"On the road · a wheel that will not turn","before":["A loaded wagon leans into the verge, one wheel sunk at an awkward angle. Two travelers have spread a blanket for the unloaded goods. A third holds up a broken length of wood and gives it a look no amount of optimism is going to improve."],"after":["A loaded wagon leans into the verge, one wheel sunk at an awkward angle. Two travelers have spread a blanket for the unloaded goods. A third holds up a broken length of wood and gives it a look no amount of optimism is going to improve.","The blanket keeps the goods out of the dirt while the tilted wagon blocks an easy return to travel. The broken wood gives you something concrete to inspect. You can ask what assistance is wanted before lifting, repairing, or choosing to pass on."]},{"global":"ECHO_TRANSITION_DATA","path":["beats","7"],"field":"read","id":"tr-camp","title":"A night on the journey · what travels with you","before":["At the night’s stopping place, boots are set within reach and tomorrow’s route is checked once more. Beyond the small circle of conversation, the world continues without asking for an explanation. For a little while, there is time for an ordinary question."],"after":["At the night’s stopping place, boots are set within reach and tomorrow’s route is checked once more. Beyond the small circle of conversation, the world continues without asking for an explanation. For a little while, there is time for an ordinary question.","The checked route and reachable boots keep tomorrow close without filling the whole evening. There is room to choose a watch and agree how to wake one another. A conversation here can be ordinary, private, or left until morning."]},{"global":"ECHO_TRANSITION_DATA","path":["beats","8"],"field":"read","id":"tr-threshold","title":"Waterdeep · choose a first destination","before":["The road narrows between carts and handbarrows before the city opens around you. Bells answer from different directions. A porter lifts a parcel above the crowd and shouts an address as if everyone in the world ought to know it. For the first time in days, the route has more turns than the map can conveniently explain."],"after":["The road narrows between carts and handbarrows before the city opens around you. Bells answer from different directions. A porter lifts a parcel above the crowd and shouts an address as if everyone in the world ought to know it. For the first time in days, the route has more turns than the map can conveniently explain.","The shouted address rises over wheels and foot traffic, then disappears into the next call. You can stop clear of the busiest flow and choose a landmark before following a street. Asking directions remains an option even with a map in hand."]},{"global":"ECHO_TRANSITION_DATA","path":["beats","9"],"field":"read","id":"tr-portal","title":"The Yawning Portal · a table beside the unknown","before":["Warm conversation gives way around a dark circle in the floor. A rope shifts against the well’s rim; nearby, somebody is explaining a route with crumbs and a knife. Behind the bar, a man watches the room as if he has heard enough brave plans to value the quiet ones."],"after":["Warm conversation gives way around a dark circle in the floor. A rope shifts against the well’s rim; nearby, somebody is explaining a route with crumbs and a knife. Behind the bar, a man watches the room as if he has heard enough brave plans to value the quiet ones.","The well interrupts the public floor as surely as a doorway. Conversation gathers around it without requiring you to descend. You can find a place to sit, watch the rope, or ask the man behind the bar about a safer first introduction."]},{"global":"ECHO_TRANSITION_DATA","path":["beats","10"],"field":"read","id":"tr-dracuseth","title":"Dracuseth · hear the account before interpreting it","before":["Dracuseth moves a chair out from the table. “You have had a long road. Tell me what happened in your words. I can wait until you have eaten.”"],"after":["Dracuseth moves a chair out from the table. “You have had a long road. Tell me what happened in your words. I can wait until you have eaten.”","The offered chair makes the meal possible before an explanation is required. Dracuseth leaves space for the account you choose to give. You can ask for practical help without treating every private discovery as part of the introduction."]},{"global":"ECHO_TRANSITION_DATA","path":["beats","11"],"field":"read","id":"tr-courtyard","title":"Mending Court · a doorway they can choose","before":["A passage opens into a small court shared by several doorways. Washing moves above a well. A covered table bears a repair someone has not finished, and the space smells faintly of paste, wood and somebody’s supper. Dracuseth pauses at the entrance. “People live here. See if you would like to be among them.”"],"after":["A passage opens into a small court shared by several doorways. Washing moves above a well. A covered table bears a repair someone has not finished, and the space smells faintly of paste, wood and somebody’s supper. Dracuseth pauses at the entrance. “People live here. See if you would like to be among them.”","The well, shared passage, and unfinished repair make the court a working home before it is anyone's opportunity. Several doors open onto the same space. You can ask about access, quiet, and lodging without assuming a room has been set aside for you."]},{"global":"ECHO_TRANSITION_DATA","path":["beats","12"],"field":"read","id":"tr-neighbors","title":"Two neighbors · a small thing that makes a home","before":["Nessa studies the legs of a heavy press while Orenna studies the space it is blocking. “It must go somewhere,” Nessa says. “Agreed,” Orenna replies, “but somewhere is not the middle of the passage.” Their disagreement has the comfortable sound of one that expects to be solved."],"after":["Nessa studies the legs of a heavy press while Orenna studies the space it is blocking. “It must go somewhere,” Nessa says. “Agreed,” Orenna replies, “but somewhere is not the middle of the passage.” Their disagreement has the comfortable sound of one that expects to be solved.","The press is heavy enough that its position affects everyone passing through. Both neighbors have a need that can be heard before a solution is offered. There is room to help, suggest a different place, or simply introduce yourselves."]},{"global":"ECHO_TRANSITION_DATA","path":["beats","13"],"field":"read","id":"tr-next","title":"The next morning · choose what the city is for","before":["The city is already at work when the next page of your plans is opened. There is room for two appointments, perhaps one useful errand, and whatever the day refuses to keep tidy."],"after":["The city is already at work when the next page of your plans is opened. There is room for two appointments, perhaps one useful errand, and whatever the day refuses to keep tidy.","Appointments and errands can share the page with the expedition you are considering. Each needs a time and a place before it becomes a commitment. You can leave the day partly open for people whose plans differ from yours."]},{"global":"ECHO_TRANSITION_DATA","path":["homecomings","0"],"field":"read","id":"neutral","title":"News before conclusions","before":"People make room for your account. Someone brings water. No one raises a toast before they know whose names belong in it.","after":"People make room for your account. Someone brings water. No one raises a toast before they know whose names belong in it.\n\nThe offered water gives the conversation a moment to settle. You can begin with what was witnessed and leave unanswered fates clearly unanswered. The people listening have time to ask what help is still needed."},{"global":"ECHO_TRANSITION_DATA","path":["homecomings","1"],"field":"read","id":"success","title":"A celebration with names remembered","before":"A small cheer begins at one table and travels farther than its first speaker intended. Then someone makes room for the names of those who will not hear it, and the noise softens into something worth keeping.","after":"A small cheer begins at one table and travels farther than its first speaker intended. Then someone makes room for the names of those who will not hear it, and the noise softens into something worth keeping.\n\nThe softened celebration makes room for more than one kind of return. You can name the successes that deserve thanks and the losses that deserve care. Neither has to erase the other from the account."},{"global":"ECHO_TRANSITION_DATA","path":["homecomings","2"],"field":"read","id":"mixed","title":"Gratitude beside grief","before":"Thanks and condolences arrive in the same conversation. A meal is offered, a chair is left quiet, and people begin asking what they can do now.","after":"Thanks and condolences arrive in the same conversation. A meal is offered, a chair is left quiet, and people begin asking what they can do now.\n\nThe spare chair and offered meal give the news somewhere to land. You can describe what was saved, what was lost, and what remains undecided. A practical request may be easier to answer than a promise to mend everything."},{"global":"ECHO_TRANSITION_DATA","path":["homecomings","3"],"field":"read","id":"unfinished","title":"A return for help","before":"The map is brought closer to the lamplight. “Start with where you stopped,” someone says. “Then tell us what you need to go back.”","after":"The map is brought closer to the lamplight. “Start with where you stopped,” someone says. “Then tell us what you need to go back.”\n\nLamplight reaches the checked route and stops at its unfinished edge. You can point to the last safe position and the questions beyond it. Supplies, help, or time may change the next attempt without rewriting this one."},{"global":"ECHO_COURTYARD_DATA","path":["beats","0"],"field":"read","id":"mc-arrival","title":"Arrival · a place with its own day","before":["Beyond the passage, a bucket knocks softly against the well’s rim. Someone has laid a cloth over a half-finished repair. Two neighbors pause beside a heavy press: one measures the space it needs, while the other measures the space everyone else will have left."],"after":["Beyond the passage, a bucket knocks softly against the well’s rim. Someone has laid a cloth over a half-finished repair. Two neighbors pause beside a heavy press: one measures the space it needs, while the other measures the space everyone else will have left.","The well and covered repair occupy a space people already share, while the press narrows the passage between them. You can see why both neighbors are measuring. An introduction can begin with a greeting before it becomes an offer to move something."]},{"global":"ECHO_COURTYARD_DATA","path":["beats","1"],"field":"read","id":"mc-terms","title":"Lodging · agree what home means for now","before":["Nessa opens both doors and waits outside while you look. The larger room has space to sleep; the smaller could become several different things. “Tell me what you need first,” she says. “Then we can see whether these rooms can provide it.”"],"after":["Nessa opens both doors and waits outside while you look. The larger room has space to sleep; the smaller could become several different things. “Tell me what you need first,” she says. “Then we can see whether these rooms can provide it.”","Two open doors give you a chance to inspect the rooms before discussing a bargain. The smaller space has no purpose assigned to you yet. You can ask about access, privacy, storage, and shared use while Nessa waits for your needs."]},{"global":"ECHO_COURTYARD_DATA","path":["beats","2"],"field":"read","id":"mc-unpack","title":"First evening · one small choice","before":["The court settles into evening sounds: a shutter, a last bucket of water, the scrape of a chair beneath the awning. There is no ceremony waiting for you. There is simply enough room for someone else to sit down."],"after":["The court settles into evening sounds: a shutter, a last bucket of water, the scrape of a chair beneath the awning. There is no ceremony waiting for you. There is simply enough room for someone else to sit down.","The awning shelters a place to sit while the day's last chores finish around it. The scrape of a chair leaves the choice of joining to you. A first evening need not become a public account of everything in your packs."]},{"global":"ECHO_COURTYARD_DATA","path":["beats","3"],"field":"read","id":"mc-return-1","title":"First return · recognition without a reward speech","before":["Orenna moves her basket from the passage as you approach. “There is room,” she says. From the bindery, Nessa looks up long enough to offer a greeting, then sets her work safely aside. The court has had a day of its own while you were gone."],"after":["Orenna moves her basket from the passage as you approach. “There is room,” she says. From the bindery, Nessa looks up long enough to offer a greeting, then sets her work safely aside. The court has had a day of its own while you were gone.","The clear passage lets you bring equipment in without interrupting the bindery's work. Nessa sets that work aside carefully rather than abandoning it. You can ask what changed here before choosing which news from below to share."]},{"global":"ECHO_COURTYARD_DATA","path":["beats","4"],"field":"read","id":"mc-supper","title":"A later supper · meet the Fen siblings","before":["Jori sets two bowls down, counts the chairs, and asks before bringing any more. Pellan is trying to fold a stall cloth around a basket that plainly disagrees with him. “We are considering a better stall,” Jori says. “Apparently the basket intends to stay here.”"],"after":["Jori sets two bowls down, counts the chairs, and asks before bringing any more. Pellan is trying to fold a stall cloth around a basket that plainly disagrees with him. “We are considering a better stall,” Jori says. “Apparently the basket intends to stay here.”","The chairs and bowls give Jori a practical count to make. Pellan's awkward basket offers a problem small enough to discuss over supper. You can offer a hand or an opinion without taking responsibility for their whole livelihood."]},{"global":"ECHO_COURTYARD_DATA","path":["beats","5"],"field":"read","id":"mc-return-2","title":"Second return · life has continued","before":["One chair has acquired a new peg. A line of washing has moved to make better use of the sun. The table is occupied by ordinary work, but a space is cleared when you arrive. Someone asks how long you can stay before your next errand."],"after":["One chair has acquired a new peg. A line of washing has moved to make better use of the sun. The table is occupied by ordinary work, but a space is cleared when you arrive. Someone asks how long you can stay before your next errand.","The new peg and moved washing are changes you can see without asking anyone to explain them. The cleared space offers room for an account when you are ready. Your next errand is still a question, not a schedule the household has chosen."]},{"global":"ECHO_COURTYARD_DATA","path":["beats","6"],"field":"read","id":"mc-quiet","title":"Aven’s request · share the day fairly","before":["At the landing desk, Aven starts a line again, stops, and puts the chalk down. “Could I borrow half an hour of quiet?” they ask. “I can move the practice after that. I am trying to pass this without keeping everyone awake.”"],"after":["At the landing desk, Aven starts a line again, stops, and puts the chalk down. “Could I borrow half an hour of quiet?” they ask. “I can move the practice after that. I am trying to pass this without keeping everyone awake.”","The chalk rests beside an unfinished line at the landing desk. Aven's request has a time limit and a reason you can understand. You can agree, suggest another place, or ask what noise would make practice possible for everyone."]},{"global":"ECHO_COURTYARD_DATA","path":["beats","7"],"field":"read","id":"mc-return-3","title":"Third return · something familiar","before":["Evening finds the court midway through its usual argument with unfinished work. A chair is turned toward the light. Someone has saved a place at the table, with no assumption about how long you will stay. For a moment, returning is an ordinary thing."],"after":["Evening finds the court midway through its usual argument with unfinished work. A chair is turned toward the light. Someone has saved a place at the table, with no assumption about how long you will stay. For a moment, returning is an ordinary thing.","The turned chair catches what remains of the evening light, while work still waits around the table. A saved place offers company without claiming your whole night. You can sit, help with a task, or ask for a quiet corner."]},{"global":"ECHO_COURTYARD_DATA","path":["beats","8"],"field":"read","id":"mc-dracuseth","title":"Dracuseth · a useful promise with limits","before":["Dracuseth waits until the account is finished before reaching for the map. “What needs doing here while you are away?” he asks. “Name the task, and tell me what would count as enough.”"],"after":["Dracuseth waits until the account is finished before reaching for the map. “What needs doing here while you are away?” he asks. “Name the task, and tell me what would count as enough.”","His hand reaches toward the map only after listening. A named task can be smaller than a promise to keep the whole city safe. You can agree on limits and a way to send word before asking him to act while you are away."]},{"global":"ECHO_COURTYARD_DATA","path":["beats","9"],"field":"read","id":"mc-improvement","title":"Make a mark · one useful improvement","before":["There is room for a shelf here, or a curtain, or perhaps nothing more complicated than a seat that fits its owner. The space does not have to become grand to become more useful."],"after":["There is room for a shelf here, or a curtain, or perhaps nothing more complicated than a seat that fits its owner. The space does not have to become grand to become more useful.","A shelf needs space, a curtain needs an agreed boundary, and a useful seat needs someone who wants it there. You can ask the people sharing this corner before beginning work. Improving a home can start with one ordinary change."]},{"global":"ECHO_COURTYARD_DATA","path":["beats","10"],"field":"read","id":"mc-disturbance","title":"Optional later disturbance · a doorway that was not there","before":["For several breaths, the patched wall beyond the table shows the frame of a different doorway. Its edge is clear enough to draw. Then the patch is simply a patch again, while the ordinary sounds of the court continue."],"after":["For several breaths, the patched wall beyond the table shows the frame of a different doorway. Its edge is clear enough to draw. Then the patch is simply a patch again, while the ordinary sounds of the court continue.","The brief outline has vanished, leaving the repaired wall available to examine. You can compare sketches or ask who saw the same edge. The ordinary sounds do not explain the doorway, and its appearance gives no instruction to open it."]},{"global":"ECHO_EXPEDITION_DATA","path":["readAloud","0"],"field":"text","id":"departure","title":"Before setting out","before":"There is space on the route sheet for what you hope to find, and another line for the way home. Before you leave, what would make you turn back?","after":"There is space on the route sheet for what you hope to find, and another line for the way home. Before you leave, what would make you turn back?\n\nThe route sheet can name a stopping point without claiming the journey has happened. Check who carries the light and how you will recognize the return turn. Each person has room to name a limit before the first step."},{"global":"ECHO_EXPEDITION_DATA","path":["readAloud","1"],"field":"text","id":"retreat","title":"Choosing to withdraw","before":"For now, the next step is back along the way you know. What have you learned that you want to remember, and what must be checked before you return?","after":"For now, the next step is back along the way you know. What have you learned that you want to remember, and what must be checked before you return?\n\nA marked turn can guide the next step while unanswered passages remain behind you. You can account for companions and carried discoveries before moving on. Turning back leaves those questions open without erasing what you have already learned."},{"global":"ECHO_EXPEDITION_DATA","path":["readAloud","2"],"field":"text","id":"rest","title":"A pause in a checked refuge","before":"For a while, you can stop moving. Who takes the first watch, what light do you keep, and what would wake the others?","after":"For a while, you can stop moving. Who takes the first watch, what light do you keep, and what would wake the others?\n\nThe stopping place needs a checked exit, a watch, and a way to call the others. You can agree which sounds deserve attention before anyone sleeps. A pause can be chosen here without promising that recovery is already complete."},{"global":"ECHO_EXPEDITION_DATA","path":["readAloud","3"],"field":"text","id":"return","title":"Returning to familiar ground","before":"You have been here before. The route no longer begins as an empty page. Where do you pause to check your bearings before going farther?","after":"You have been here before. The route no longer begins as an empty page. Where do you pause to check your bearings before going farther?\n\nYour earlier notes give you landmarks to compare with what is visible now. Check a door, a mark, or a familiar turn before relying on the whole route. Anything changed can be recorded without treating the rest as unexplored again."},{"global":"ECHO_EXPEDITION_DATA","path":["readAloud","4"],"field":"text","id":"debrief","title":"Back at the agreed meeting place","before":"Set down the things you brought back. Which discovery matters most, who still needs help, and what do you want to do before the next descent?","after":"Set down the things you brought back. Which discovery matters most, who still needs help, and what do you want to do before the next descent?\n\nThe returned equipment and records give the account something concrete to begin with. You can separate what was seen from what was suspected, then decide who should hear each part. An unfinished question may belong at the top of the next page."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","0","beats","0"],"field":"say","id":"pc-trista-redbrand","title":"The place you choose to stand","before":"There is room to keep watch, scout ahead, or stay close to the others. Trista, who would you want beside you if something unexpected turned up?","after":"There is room to keep watch, scout ahead, or stay close to the others. Trista, who would you want beside you if something unexpected turned up?\n\nThe choice can begin with a position and a companion rather than an explanation. You can name what you want watched and what would bring you back to the others. No one needs a private discovery to understand a request for caution."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","0","beats","1"],"field":"say","id":"pc-trista-aftermath","title":"A favor with no price","before":"A person you helped offers a small place at their table. “I cannot repay everything. Is there one thing I can do for you?”","after":"A person you helped offers a small place at their table. “I cannot repay everything. Is there one thing I can do for you?”\n\nThe offered place makes room for a reply without setting its price. You can ask for an ordinary kindness, decline, or leave the matter for another day. Gratitude does not require you to reveal what you have kept to yourself."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","0","beats","2"],"field":"say","id":"pc-trista-forge","title":"The keeper is a choice","before":"You can keep this where it is, carry it away, or make a record before anyone touches it. What would make you willing to trust another person with the decision?","after":"You can keep this where it is, carry it away, or make a record before anyone touches it. What would make you willing to trust another person with the decision?\n\nThe object's position gives everyone a common starting point before hands move toward it. You can name the record you want made and the limits you want respected. Trust can begin with a specific permission rather than surrendering the whole decision."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","0","beats","3"],"field":"say","id":"pc-trista-waterdeep","title":"Mara asks for the whole truth","before":"Mara says, “Tell me what you can promise. I would rather know the limit than find it later.”","after":"Mara says, “Tell me what you can promise. I would rather know the limit than find it later.”\n\nMara's question leaves room for a narrow answer. You can name what you will do and where your agreement ends. A clear limit gives both of you something to return to if another request arrives later."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","0","beats","4"],"field":"say","id":"pc-trista-depths","title":"Privacy without isolation","before":"One person wants the original sealed. Another wants a copy available to anyone in danger. Both ask what you would need before trusting them.","after":"One person wants the original sealed. Another wants a copy available to anyone in danger. Both ask what you would need before trusting them.\n\nThe two proposals differ in access as well as purpose. You can ask what danger each person is trying to prevent and who would inspect the copy. Keeping the original safe need not settle every question about sharing its record."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","0","beats","5"],"field":"say","id":"pc-trista-resolution","title":"What you are willing to carry","before":"You once kept a small thing because it was yours to understand. What, now, are you willing to keep—and what responsibility belongs with someone else?","after":"You once kept a small thing because it was yours to understand. What, now, are you willing to keep—and what responsibility belongs with someone else?\n\nA keeper's name can be written beside a limit and a date to ask again. You can choose what responsibility remains yours without promising it forever. The people affected deserve a voice in what follows."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","1","beats","0"],"field":"say","id":"pc-pebble-redbrand","title":"Mark the way back","before":"Pebble, what would help you recognize the way back? You have chalk, familiar shapes, and friends who can check the route with you.","after":"Pebble, what would help you recognize the way back? You have chalk, familiar shapes, and friends who can check the route with you.\n\nA shape in the stone or a mark at a turn can become a landmark without being a perfect map. You can ask a friend to check it with you. Learning a route can happen one recognizable place at a time."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","1","beats","1"],"field":"say","id":"pc-pebble-aftermath","title":"The makers’ mark","before":"The smith turns the hammer carefully. “Good work. Who made this for you? What would you want them to know you have done with it?”","after":"The smith turns the hammer carefully. “Good work. Who made this for you? What would you want them to know you have done with it?”\n\nThe hammer rests in careful hands long enough for its marks to be studied. You can tell the smith what you know of its makers and leave uncertain details open. A message home can begin with one useful drawing."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","1","beats","2"],"field":"say","id":"pc-pebble-forge","title":"Something better than a shiny rock","before":"A seam catches the light. Some pieces shine more than others, but the marks around it show people once worked carefully here. What would you like to learn before you take a piece?","after":"A seam catches the light. Some pieces shine more than others, but the marks around it show people once worked carefully here. What would you like to learn before you take a piece?\n\nThe shining seam offers a place to look before anyone tastes or breaks a sample. The old working marks may tell you how carefully it was handled. You can ask for a small, controlled comparison instead of claiming the whole vein."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","1","beats","3"],"field":"say","id":"pc-pebble-waterdeep","title":"Your own route home","before":"The city is loud, but three landmarks now make sense: the place you left, the turn you remember, and where your friends will wait. Which route do you want to show them?","after":"The city is loud, but three landmarks now make sense: the place you left, the turn you remember, and where your friends will wait. Which route do you want to show them?\n\nThree known landmarks can be enough to make the next journey manageable. You can choose where the party will meet if the streets separate you. Showing a familiar turn gives someone else a chance to learn it too."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","1","beats","4"],"field":"say","id":"pc-pebble-depths","title":"A letter from the mountain","before":"“We would like to know the places you have learned. Could you send a map someone else could follow? There is a young traveler here who is frightened of taking the first step.”","after":"“We would like to know the places you have learned. Could you send a map someone else could follow? There is a young traveler here who is frightened of taking the first step.”\n\nThe request values a route another traveler can recognize. You can include where you hesitated and how you checked your bearings. A warning from experience may help more than pretending you were never frightened."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","1","beats","5"],"field":"say","id":"pc-pebble-resolution","title":"The one who knows the way","before":"Someone asks you the question you once needed to ask: “How do I get there without losing everyone?” What do you tell them?","after":"Someone asks you the question you once needed to ask: “How do I get there without losing everyone?” What do you tell them?\n\nThe question leaves room for a landmark, a meeting place, and permission to ask for help. You can offer the tools that worked for you. The next traveler need not take every step alone to call the journey their own."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","2","beats","0"],"field":"say","id":"pc-donavan-redbrand","title":"The useful discrepancy","before":"Two accounts agree on a name but disagree about what it means. What would you need to record before deciding which one to trust?","after":"Two accounts agree on a name but disagree about what it means. What would you need to record before deciding which one to trust?\n\nThe shared name gives the accounts a point of comparison, while their disagreement remains visible. You can record who supplied each version and what would test it. Choosing to investigate need not mean endorsing either explanation."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","2","beats","1"],"field":"say","id":"pc-donavan-aftermath","title":"Dianna’s first reply","before":"“Donavan—send the ordinary details too. What did you eat, and who made you laugh? For the measurements, keep the result you expected separate from the one you found. I would like both versions. Love, Dianna.”","after":"“Donavan—send the ordinary details too. What did you eat, and who made you laugh? For the measurements, keep the result you expected separate from the one you found. I would like both versions. Love, Dianna.”\n\nThe ordinary questions sit beside the measurements in the same letter. You can answer either in your own order and keep the observations separate from the theory. Dianna has left room for a life beyond the numbers."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","2","beats","2"],"field":"say","id":"pc-donavan-forge","title":"A finding someone can reproduce","before":"You can record where you stood, what happened, and what changed. Which comparison would help someone distinguish an ordinary magical effect from your explanation?","after":"You can record where you stood, what happened, and what changed. Which comparison would help someone distinguish an ordinary magical effect from your explanation?\n\nA position, a time, and a recorded change make a comparison someone else could check. You can decide what observation is safe to repeat. A surprising result can stay surprising until another test earns an explanation."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","2","beats","3"],"field":"say","id":"pc-donavan-waterdeep","title":"The redacted report","before":"“I can copy what you send,” the correspondent says. “Tell me who could be harmed by the details, and which conclusions you are ready to put your name beside.”","after":"“I can copy what you send,” the correspondent says. “Tell me who could be harmed by the details, and which conclusions you are ready to put your name beside.”\n\nCopying makes a private record easier to carry beyond the people who made it. You can name what is withheld and why before approving a version. A reader should be able to tell your observations from your conclusions."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","2","beats","4"],"field":"say","id":"pc-donavan-depths","title":"A rival changes one of your conclusions","before":"Ilyra sets two records beside yours. “This part supports you. This part does not. Will you help me find out why?”","after":"Ilyra sets two records beside yours. “This part supports you. This part does not. Will you help me find out why?”\n\nThe records remain beside one another, including the disagreement. You can ask how each was made before deciding whether to repeat a measurement. A conflicting result is a reason to investigate rather than discard a witness."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","2","beats","5"],"field":"say","id":"pc-donavan-resolution","title":"The archive you leave behind","before":"Your record could outlive everyone who remembers why it was written. What must a future reader be able to check—and what do they need permission to use?","after":"Your record could outlive everyone who remembers why it was written. What must a future reader be able to check—and what do they need permission to use?\n\nDates, contributors, and limits can make the record useful to someone you will never meet. You can preserve unanswered questions with the method that exposed them. Permission to use a discovery can be written as carefully as the discovery itself."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","3","beats","0"],"field":"say","id":"pc-ringgo-redbrand","title":"The exit you leave open","before":"You notice where someone would run and what would make surrender believable. What would you need to offer for this to end without another body?","after":"You notice where someone would run and what would make surrender believable. What would you need to offer for this to end without another body?\n\nAn exit can be watched without closing every chance to speak. You can name terms that someone cornered might understand and ask who can honor them. A surrender remains a choice until the other person accepts it."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","3","beats","1"],"field":"say","id":"pc-ringgo-aftermath","title":"A job with a receipt","before":"“There is a price for the work, written here. Bring the goods back, and I pay you. No hidden part of the bargain.”","after":"“There is a price for the work, written here. Bring the goods back, and I pay you. No hidden part of the bargain.”\n\nThe written price gives the offer a boundary you can inspect. You can ask what condition the goods must be in and who receives them. Ordinary work can begin with an agreement clear enough to repeat aloud."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","3","beats","2"],"field":"say","id":"pc-ringgo-forge","title":"An old method, a different purpose","before":"You know a way to approach without being seen. This time, who is that knowledge meant to keep alive?","after":"You know a way to approach without being seen. This time, who is that knowledge meant to keep alive?\n\nA quiet approach leaves choices about who comes with you and where to meet afterward. You can explain those practical details without rehearsing a violent ending. Keeping someone alive may require knowing when to return."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","3","beats","3"],"field":"say","id":"pc-ringgo-waterdeep","title":"The contact who offers a choice","before":"“I know work you used to do,” says the visitor. “I need something different now. Will you hear it before you decide?”","after":"“I know work you used to do,” says the visitor. “I need something different now. Will you hear it before you decide?”\n\nThe visitor has named an old connection without deciding your answer for you. You can hear the proposed work, set conditions for the meeting, or refuse. A familiar past need not make a new bargain inevitable."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","3","beats","4"],"field":"say","id":"pc-ringgo-depths","title":"Finish a debt without creating another","before":"“I want this to stop,” they tell you. “That does not mean I want someone else dead. What can you actually change?”","after":"“I want this to stop,” they tell you. “That does not mean I want someone else dead. What can you actually change?”\n\nThe request separates an end to the problem from another death. You can ask what safety would look like tomorrow and what help is wanted now. Any promise you make can name a practical limit."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","3","beats","5"],"field":"say","id":"pc-ringgo-resolution","title":"The name on your door","before":"If someone comes looking for your help years from now, what work do you want them to believe you do?","after":"If someone comes looking for your help years from now, what work do you want them to believe you do?\n\nThe next answer can define the work you accept and the work you refuse. You can leave old records intact without letting them speak for every future choice. A new client has time to hear your terms."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","4","beats","0"],"field":"say","id":"pc-aldric-redbrand","title":"A seal and a chance to act differently","before":"A formal phrase catches at a memory: a desk, your hand, a seal pressed into wax. Nothing proves where it happened. What do you do with the feeling?","after":"A formal phrase catches at a memory: a desk, your hand, a seal pressed into wax. Nothing proves where it happened. What do you do with the feeling?\n\nThe remembered desk and seal arrive without a date or a witness. You can describe the details privately, set them aside, or seek something that could confirm them. A feeling deserves attention without becoming proof."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","4","beats","1"],"field":"say","id":"pc-aldric-aftermath","title":"The ring leaves an impression","before":"The crest is damaged, but a careful drawing can preserve what remains. Who, if anyone, would you trust with a copy?","after":"The crest is damaged, but a careful drawing can preserve what remains. Who, if anyone, would you trust with a copy?\n\nA drawing can keep the damaged crest available for comparison while the ring stays on your hand. You can decide whose eyes may see it and what name accompanies the inquiry. The copy need not carry every part of your history."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","4","beats","2"],"field":"say","id":"pc-aldric-forge","title":"The echo in an old measurement","before":"For a moment, a remembered rhythm lines up with the pulse beneath the stone. Then it slips away. It is familiar, but familiarity is not an explanation.","after":"For a moment, a remembered rhythm lines up with the pulse beneath the stone. Then it slips away. It is familiar, but familiarity is not an explanation.\n\nThe rhythm fades before it offers an answer. You can note where it occurred and ask whether anyone noticed the same timing. A shared observation might support an inquiry without claiming the memory is complete."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","4","beats","3"],"field":"say","id":"pc-aldric-waterdeep","title":"Two records and a living witness","before":"The archivist places a copy beside your sketch. “This tells us who held the office. It does not tell us what kind of person he was. For that, we need someone who was there.”","after":"The archivist places a copy beside your sketch. “This tells us who held the office. It does not tell us what kind of person he was. For that, we need someone who was there.”\n\nThe copied appointment records an office and a holder. A witness could describe the person behind the title, if they are willing. You can ask how to approach them without turning their account into a demand for forgiveness."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","4","beats","4"],"field":"say","id":"pc-aldric-depths","title":"Halaster did bring you back","before":"An experiment record carries three details a public rumor would not: the broken ring finger, the uneven scar, and the moment your breathing did not return. A later entry reads, “Continuity achieved. Subject departed. Memory incomplete.”","after":"An experiment record carries three details a public rumor would not: the broken ring finger, the uneven scar, and the moment your breathing did not return. A later entry reads, “Continuity achieved. Subject departed. Memory incomplete.”\n\nThe identifying details can be compared with your own body and memory. The later entry names an outcome but leaves its explanation narrow. You can preserve the record without accepting the writer's right to define who you are now."},{"global":"ECHO_CHARACTER_STORIES","path":["arcs","4","beats","5"],"field":"say","id":"pc-aldric-resolution","title":"A life that is yours","before":"The cause of your return is no longer the only question. There are people alive now who can say what they need. Which promise are you willing to make without asking them to forgive you?","after":"The cause of your return is no longer the only question. There are people alive now who can say what they need. Which promise are you willing to make without asking them to forgive you?\n\nA request from someone living can be heard on its own terms. You can offer a specific act and let them decide whether it helps. Atonement need not depend on a stranger agreeing to erase the past."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","0","scenes","0"],"field":"read","id":"chapter-character-trista-1-1","title":"The warning at a quiet table","before":"Mara turns a folded commission so only you can read it. “They are asking after something marked BELOW. I know what they want. I do not know who has it.”","after":"Mara turns a folded commission so only you can read it. “They are asking after something marked BELOW. I know what they want. I do not know who has it.”\n\nThe folded paper makes this a private offer rather than an announcement to the room. You can inspect its terms before speaking of anything you carry. Knowing someone is asking does not establish who has answered them."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","0","scenes","1"],"field":"read","id":"chapter-character-trista-1-2","title":"A job with an exit","before":"“No delivery tonight,” Mara says. “We check the address, learn what is being offered, and leave. Tell me the line you will not cross.”","after":"“No delivery tonight,” Mara says. “We check the address, learn what is being offered, and leave. Tell me the line you will not cross.”\n\nAn address can be checked without making a delivery. You can agree on a meeting point and a reason to leave before setting out. Mara waits for the limit you choose rather than naming it for you."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","1","scenes","0"],"field":"read","id":"chapter-character-trista-2-1","title":"Two copies of the offer","before":"The second copy has a line missing from the first: delivery includes permission for a suppression examination. The signatures do not explain who removed it.","after":"The second copy has a line missing from the first: delivery includes permission for a suppression examination. The signatures do not explain who removed it.\n\nThe missing line can be compared word for word with the earlier copy. You can note where the versions came from and who handled them. A difference in the paper does not identify the hand that caused it."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","1","scenes","1"],"field":"read","id":"chapter-character-trista-2-2","title":"Ask for the whole bargain","before":"Mara listens until you finish. “Then ask me exactly. I can tell you what I was paid to do, what I guessed, and what I was afraid to ask.”","after":"Mara listens until you finish. “Then ask me exactly. I can tell you what I was paid to do, what I guessed, and what I was afraid to ask.”\n\nHer answer offers separate pieces: paid work, guesses, and questions left unasked. You can take them in that order and decide what needs checking. Hearing the explanation need not settle whether you trust it."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","2","scenes","0"],"field":"read","id":"chapter-character-trista-3-1","title":"The comparison she permits","before":"The chalk line gives you something to compare: one mark, one fixed lamp, and the same place viewed twice. You can stop before anyone touches what you brought.","after":"The chalk line gives you something to compare: one mark, one fixed lamp, and the same place viewed twice. You can stop before anyone touches what you brought.\n\nThe fixed lamp and chalk mark make the two views comparable. You can inspect the arrangement without putting the object into it. A clear stopping point leaves the next step yours to choose."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","2","scenes","1"],"field":"read","id":"chapter-character-trista-3-2","title":"Two accounts of one shadow","before":"The witness describes the edge before you show your sketch. It matches one detail and disagrees on another. Neither account has to disappear to make the page tidy.","after":"The witness describes the edge before you show your sketch. It matches one detail and disagrees on another. Neither account has to disappear to make the page tidy.\n\nThe matching detail and the disagreement both belong in the account. You can ask how the witness saw the edge before offering your explanation. An independent description is useful even when it leaves a question open."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","3","scenes","0"],"field":"read","id":"chapter-character-trista-4-1","title":"Four spaces on the table","before":"The custodian lays out four blank cards. “Who holds it? Who may inspect it? What may be copied? When do we ask again?”","after":"The custodian lays out four blank cards. “Who holds it? Who may inspect it? What may be copied? When do we ask again?”\n\nFour separate cards keep possession from becoming unlimited permission. You can answer one question while leaving another for later. The arrangement can name a review date rather than pretending no future disagreement is possible."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","3","scenes","1"],"field":"read","id":"chapter-character-trista-4-2","title":"A request outside the terms","before":"A message arrives asking for a copy before the agreed review. It names a real need and leaves one important question unanswered: who else will receive it?","after":"A message arrives asking for a copy before the agreed review. It names a real need and leaves one important question unanswered: who else will receive it?\n\nThe earlier agreement gives the new request something to be compared against. You can ask who else will receive the copy before allowing an exception. Urgency can be heard without making private information public by default."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","4","scenes","0"],"field":"read","id":"chapter-character-trista-5-1","title":"What the arrangement leaves behind","before":"The storage place is ordinary in daylight. There is room for a label, a second key, or nothing at all. The next choice is about who will answer when someone asks to use it.","after":"The storage place is ordinary in daylight. There is room for a label, a second key, or nothing at all. The next choice is about who will answer when someone asks to use it.\n\nDaylight gives you an ordinary place to examine before choosing a keeper. A label or key would change who can use the space. You can ask the people sharing it before making either change."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","4","scenes","1"],"field":"read","id":"chapter-character-trista-5-2","title":"Mara’s next invitation","before":"Mara sets down a new offer without reaching for your things. “This time, I wrote the terms first. You can still say no.”","after":"Mara sets down a new offer without reaching for your things. “This time, I wrote the terms first. You can still say no.”\n\nThe untouched belongings keep the offer separate from the things it concerns. You can read the written terms, question them, or leave them unanswered. A refusal remains possible after a careful hearing."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","5","scenes","0"],"field":"read","id":"chapter-character-pebble-1-1","title":"The mark under the repair","before":"Beneath a newer repair, a small tool mark resembles the one on your hammer. Orren sets the object down. “Similar work. Shall we find out how similar?”","after":"Beneath a newer repair, a small tool mark resembles the one on your hammer. Orren sets the object down. “Similar work. Shall we find out how similar?”\n\nThe older mark and newer repair can be inspected separately. Orren leaves the object available for comparison rather than declaring its maker. You can check the shape against your hammer and decide what question to send home."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","5","scenes","1"],"field":"read","id":"chapter-character-pebble-1-2","title":"An answer from home","before":"The reply begins with something ordinary about work at the forge. Then the writer turns to your sketch: “We know the habit of that chisel. We have not had an answer to our last letter.”","after":"The reply begins with something ordinary about work at the forge. Then the writer turns to your sketch: “We know the habit of that chisel. We have not had an answer to our last letter.”\n\nThe ordinary forge news gives the writer a life beyond the missing reply. You can copy the recognized mark and ask when the last letter was sent. A familiar chisel habit points toward an inquiry rather than an answer."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","6","scenes","0"],"field":"read","id":"chapter-character-pebble-2-1","title":"The last paid job","before":"The ledger lists wages, a delivery, and a travel advance. The line after the advance is blank. The keeper says, “Leaving was their choice. What happened afterward, I cannot tell you.”","after":"The ledger lists wages, a delivery, and a travel advance. The line after the advance is blank. The keeper says, “Leaving was their choice. What happened afterward, I cannot tell you.”\n\nThe wages and advance place the departure in a record you can inspect. The blank line marks the keeper's limit. You can ask which date or recipient might help find a later account without calling the journey a disappearance by choice."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","6","scenes","1"],"field":"read","id":"chapter-character-pebble-2-2","title":"A question before a rescue","before":"A reply, witness, or abandoned work note gives you a task more precise than “find them”: learn whether a safe return is possible and what must be left behind.","after":"A reply, witness, or abandoned work note gives you a task more precise than “find them”: learn whether a safe return is possible and what must be left behind.\n\nThe narrower task gives the next journey a purpose you can discuss. You can ask what would establish safety and whose belongings must remain untouched. The person you seek may have reasons to choose another home."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","7","scenes","0"],"field":"read","id":"chapter-character-pebble-3-1","title":"The sample and the label","before":"Two pieces look almost alike. One has a place, date, and collector written beside it. The other has only a price. Which question do you want answered first?","after":"Two pieces look almost alike. One has a place, date, and collector written beside it. The other has only a price. Which question do you want answered first?\n\nTheir similar appearance invites a closer comparison rather than a quick taste. A recorded origin can be checked; a price alone cannot supply one. You can ask how each sample was handled before deciding whether to test it."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","7","scenes","1"],"field":"read","id":"chapter-character-pebble-3-2","title":"A boundary small enough to test","before":"The test tray is no wider than your hands. “We compare this much first,” Orren says. “If it changes, we stop. A street is not a test tray.”","after":"The test tray is no wider than your hands. “We compare this much first,” Orren says. “If it changes, we stop. A street is not a test tray.”\n\nThe tray puts a visible boundary around the comparison. You can agree what counts as a change and who can call a halt. No one needs to expose a whole street to answer a question about a small sample."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","8","scenes","0"],"field":"read","id":"chapter-character-pebble-4-1","title":"Make a plan they can repeat","before":"You place the route notes where everyone can see them. “If we lose sight of each other, we meet here.” The people listening ask you to show them how they will recognize it.","after":"You place the route notes where everyone can see them. “If we lose sight of each other, we meet here.” The people listening ask you to show them how they will recognize it.\n\nThe notes offer turns and landmarks that listeners can point to. A meeting place is useful only if everyone can recognize it. You can invite questions and leave room for a correction before anyone relies on the route."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","8","scenes","1"],"field":"read","id":"chapter-character-pebble-4-2","title":"The mark that moved","before":"One familiar mark is still there. The next lies beside fresh rubble. The route has changed in one place, and you have time to choose what to do about it.","after":"One familiar mark is still there. The next lies beside fresh rubble. The route has changed in one place, and you have time to choose what to do about it.\n\nThe surviving mark gives you one reliable point beside the rubble. You can compare the changed stretch with your notes and look for a safe alternative. Returning need not mean trusting every old passage without checking."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","9","scenes","0"],"field":"read","id":"chapter-character-pebble-5-1","title":"A place for the corrections","before":"Your map has changed hands enough to show it: a repaired edge, a better turn, a warning added by someone who came back. There is space for another person’s correction.","after":"Your map has changed hands enough to show it: a repaired edge, a better turn, a warning added by someone who came back. There is space for another person’s correction.\n\nThe repaired edge and added warning show how another traveler used the page. You can ask which turn needs improving next. A useful map can keep its earlier mistakes visible while carrying a better route."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","9","scenes","1"],"field":"read","id":"chapter-character-pebble-5-2","title":"What goes home","before":"There is room in the pack for a letter, a modest sample, and the map. Someone asks, “When they see this, what do you want them to know about the places you found?”","after":"There is room in the pack for a letter, a modest sample, and the map. Someone asks, “When they see this, what do you want them to know about the places you found?”\n\nThe modest space in the pack invites a deliberate choice of what travels home. You can label a permitted sample and leave uncertain claims out of the letter. A map may tell more than a dramatic story about bravery."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","10","scenes","0"],"field":"read","id":"chapter-character-donavan-1-1","title":"One page, three columns","before":"The page has room for what happened, what you think it means, and what would change your mind. The first column is shorter than the second.","after":"The page has room for what happened, what you think it means, and what would change your mind. The first column is shorter than the second.\n\nThe separate columns keep the observation from being swallowed by its explanation. You can add a witness, place, and date to the shorter one. A blank beside the theory can name the test that would challenge it."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","10","scenes","1"],"field":"read","id":"chapter-character-donavan-1-2","title":"A question returned","before":"Dianna’s reply includes news from her own work. In the margin she has written, “Try predicting the next interval before you measure it. A pattern should risk being wrong.”","after":"Dianna’s reply includes news from her own work. In the margin she has written, “Try predicting the next interval before you measure it. A pattern should risk being wrong.”\n\nThe margin gives the next measurement a question before it gives it an answer. You can write a prediction and leave it unchanged during the test. Dianna's ordinary news remains there to answer when the work is done."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","11","scenes","0"],"field":"read","id":"chapter-character-donavan-2-1","title":"The other notebook","before":"The researcher places their notebook beside yours. “I believe your observation. I think your explanation predicts something mine does not. Shall we write both down?”","after":"The researcher places their notebook beside yours. “I believe your observation. I think your explanation predicts something mine does not. Shall we write both down?”\n\nTwo notebooks allow the methods as well as the conclusions to be compared. You can ask what each explanation expects to happen next. The discussion need not turn a disagreement into a contest of loyalty."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","11","scenes","1"],"field":"read","id":"chapter-character-donavan-2-2","title":"Predictions before the result","before":"Two folded slips lie beside the instrument. One names the expected change; the other names the expected absence. Neither can be rewritten after the reading.","after":"Two folded slips lie beside the instrument. One names the expected change; the other names the expected absence. Neither can be rewritten after the reading.\n\nThe folded slips preserve the predictions before the instrument is read. You can agree who records the result and when the slips are opened. Neither account needs a successful prediction to remain part of the record."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","12","scenes","0"],"field":"read","id":"chapter-character-donavan-3-1","title":"Read the stop condition aloud","before":"Before the apparatus is touched, the observer reads the final line: “If this limit is crossed, we stop.” There is a place on the form for a result nobody predicted.","after":"Before the apparatus is touched, the observer reads the final line: “If this limit is crossed, we stop.” There is a place on the form for a result nobody predicted.\n\nThe final line sets a boundary that can be read before hands reach for the apparatus. You can ask how the observer will recognize it. The blank result field leaves room for what the test actually shows."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","12","scenes","1"],"field":"read","id":"chapter-character-donavan-3-2","title":"The result that stays on the page","before":"Your prediction and the reading remain side by side. The rival taps the discrepancy. “We should keep this part. It tells us what to ask next.”","after":"Your prediction and the reading remain side by side. The rival taps the discrepancy. “We should keep this part. It tells us what to ask next.”\n\nThe discrepancy has a visible place beside the prediction. You can preserve the conditions of the reading and decide what deserves another comparison. An unexpected answer can guide the next question without being forced to prove either researcher right."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","13","scenes","0"],"field":"read","id":"chapter-character-donavan-4-1","title":"Three requests for one report","before":"Three requests arrive: residents ask what to watch for, a sponsor asks how to reproduce the result, and a colleague asks for the complete record. They are not asking for the same thing.","after":"Three requests arrive: residents ask what to watch for, a sponsor asks how to reproduce the result, and a colleague asks for the complete record. They are not asking for the same thing.\n\nThe three requests can be answered with different versions of the same record. You can decide what each audience needs and what permission is still missing. A public warning need not include instructions for repeating an uncertain experiment."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","13","scenes","1"],"field":"read","id":"chapter-character-donavan-4-2","title":"The sentence that might harm someone","before":"A reviewer circles a sentence. “This names a person who agreed to speak privately. Can you make the useful part true without making them a target?”","after":"A reviewer circles a sentence. “This names a person who agreed to speak privately. Can you make the useful part true without making them a target?”\n\nThe circled sentence gives you a specific point to revise. You can keep the observation while removing a name or identifying detail. Useful evidence can remain checkable without turning a private witness into public material."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","14","scenes","0"],"field":"read","id":"chapter-character-donavan-5-1","title":"Before the copy leaves","before":"The final page lists contributors, methods, limits and the date. There is one blank line: who receives this version?","after":"The final page lists contributors, methods, limits and the date. There is one blank line: who receives this version?\n\nThe date and limits give a future reader a way to place the work. You can name what this version supports and what it leaves unanswered. Its recipient is still a choice before any copy is sent."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","14","scenes","1"],"field":"read","id":"chapter-character-donavan-5-2","title":"The useful correction","before":"A reader sends a note: one detail does not match their records. Dianna has underlined the question, not your name. “This could make the next version better.”","after":"A reader sends a note: one detail does not match their records. Dianna has underlined the question, not your name. “This could make the next version better.”\n\nThe reader's differing detail offers a new source to examine. You can ask for its date and method before changing your account. A correction can be recorded openly without erasing the earlier result."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","15","scenes","0"],"field":"read","id":"chapter-character-ringgo-1-1","title":"The work written plainly","before":"The client points to three lines: the question, the payment, and what counts as delivery. “Tell me what you can establish. I am paying for that, not a story I already want to hear.”","after":"The client points to three lines: the question, the payment, and what counts as delivery. “Tell me what you can establish. I am paying for that, not a story I already want to hear.”\n\nThree written lines let you inspect the boundaries before accepting the job. You can ask who may see the answer and what evidence counts as delivery. The client has left room for a verified limit rather than demanding certainty."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","15","scenes","1"],"field":"read","id":"chapter-character-ringgo-1-2","title":"Bring back what is true","before":"You have a useful answer and a boundary: this much is verified; beyond it, the route or account remains unchecked. The client waits for your report.","after":"You have a useful answer and a boundary: this much is verified; beyond it, the route or account remains unchecked. The client waits for your report.\n\nThe useful answer can be stated alongside the unchecked edge of the work. You can give the client the evidence behind it and leave the remaining question open. Payment need not require pretending the whole route was surveyed."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","16","scenes","0"],"field":"read","id":"chapter-character-ringgo-2-1","title":"A message with a boundary","before":"The message asks for a meeting, gives a way to refuse, and contains one old detail you can choose to recognize. It does not name your former work to anyone else.","after":"The message asks for a meeting, gives a way to refuse, and contains one old detail you can choose to recognize. It does not name your former work to anyone else.\n\nThe private detail can be recognized or left unacknowledged. You can choose the people present and a safe way to refuse before answering. The invitation does not grant anyone access to your present companions."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","16","scenes","1"],"field":"read","id":"chapter-character-ringgo-2-2","title":"What help would mean","before":"“I am asking for a place to sleep and someone to look at the papers,” the visitor says. “If the answer is no, tell me before I make another promise.”","after":"“I am asking for a place to sleep and someone to look at the papers,” the visitor says. “If the answer is no, tell me before I make another promise.”\n\nThe visitor names two immediate needs rather than claiming the whole future. You can ask whose papers they are and what help is wanted with them. A place to sleep and an investigation can be considered separately."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","17","scenes","0"],"field":"read","id":"chapter-character-ringgo-3-1","title":"The other copy of the debt","before":"The second ledger records a name absent from the first: someone who lost goods or wages when the arrangement ended. It does not say that threats against the contact are justified.","after":"The second ledger records a name absent from the first: someone who lost goods or wages when the arrangement ended. It does not say that threats against the contact are justified.\n\nThe second ledger makes the affected person visible without deciding their remedy. You can compare dates and entries before approaching either side. An unfinished debt can be investigated without accepting a threat as justified."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","17","scenes","1"],"field":"read","id":"chapter-character-ringgo-3-2","title":"A chance to answer","before":"The contact reads the missing line. “I hoped that part would stay behind me.” There is space for an explanation, and space for the other person to reject it.","after":"The contact reads the missing line. “I hoped that part would stay behind me.” There is space for an explanation, and space for the other person to reject it.\n\nThe missing line stays available to both parties as the conversation begins. You can ask what was done and what repair is wanted now. An explanation may be heard without requiring the harmed person to accept it."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","18","scenes","0"],"field":"read","id":"chapter-character-ringgo-4-1","title":"A plan with names beside it","before":"The plan lists who carries the papers, who checks the destination, and who can call it off. Nobody’s name is written in a space they have not accepted.","after":"The plan lists who carries the papers, who checks the destination, and who can call it off. Nobody’s name is written in a space they have not accepted.\n\nThe unfilled roles show which parts of the plan still need consent. You can check the destination and stopping signal before assigning anyone a task. A practical boundary keeps assistance from becoming another hidden bargain."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","18","scenes","1"],"field":"read","id":"chapter-character-ringgo-4-2","title":"Check the promise in practice","before":"The signed page is ready. Ringgo can still ask one more question: “What stops this from beginning again tomorrow?”","after":"The signed page is ready. Ringgo can still ask one more question: “What stops this from beginning again tomorrow?”\n\nThe ready signature leaves a moment to examine what the page actually changes. You can ask who will check the terms afterward and what happens if they fail. An agreement needs a next day as well as a closing line."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","19","scenes","0"],"field":"read","id":"chapter-character-ringgo-5-1","title":"Close the account honestly","before":"The old file is thin enough to read in one sitting: the request, the promises, what was done, and what remains. You can close a job without pretending every wound is closed.","after":"The old file is thin enough to read in one sitting: the request, the promises, what was done, and what remains. You can close a job without pretending every wound is closed.\n\nThe thin file can preserve completed work beside unfinished harm. You can say which promise has been kept and which question still belongs to someone else. Closing the job need not make every person satisfied with its ending."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","19","scenes","1"],"field":"read","id":"chapter-character-ringgo-5-2","title":"The name on the door","before":"Someone comes looking for help and asks the simplest question: “What sort of work do you take?” This time, you get to answer before there is a bargain.","after":"Someone comes looking for help and asks the simplest question: “What sort of work do you take?” This time, you get to answer before there is a bargain.\n\nThe visitor's question offers a beginning before any price is agreed. You can name the work you will take and the limits you keep. A new reputation can grow from repeated ordinary choices."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","20","scenes","0"],"field":"read","id":"chapter-character-aldric-1-1","title":"A copy without a sacrifice","before":"The specialist moves the lamp, not your hand. “We can draw what remains. Nothing here requires taking the ring off.”","after":"The specialist moves the lamp, not your hand. “We can draw what remains. Nothing here requires taking the ring off.”\n\nThe moved lamp makes the damaged crest easier to see without forcing your hand. You can approve a drawing and decide who may keep it. Examining the ring need not include an attempt to remove it."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","20","scenes","1"],"field":"read","id":"chapter-character-aldric-1-2","title":"Two records, two keepers","before":"One record describes a commission. The other lists an appointment. They agree on one identifying detail, but they were kept by different people for different reasons.","after":"One record describes a commission. The other lists an appointment. They agree on one identifying detail, but they were kept by different people for different reasons.\n\nThe records can be read beside one another without treating either as a complete life. You can compare the identifying detail, dates, and keepers. An appointment confirms an office before it confirms the person you remember."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","21","scenes","0"],"field":"read","id":"chapter-character-aldric-2-1","title":"A meeting with an exit","before":"The intermediary explains the arrangements first: where the doors are, who may attend, and that either person can end the meeting. There will be no demand for an apology accepted on command.","after":"The intermediary explains the arrangements first: where the doors are, who may attend, and that either person can end the meeting. There will be no demand for an apology accepted on command.\n\nThe stated doors and attendance give the meeting boundaries you can understand before it begins. You can agree on a way to leave and listen without demanding a particular response. The other person keeps the same right to stop."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","21","scenes","1"],"field":"read","id":"chapter-character-aldric-2-2","title":"The act and the next need","before":"“I can tell you what happened on that day,” the witness says. “What I need now is different.” They place a practical request beside the old record.","after":"“I can tell you what happened on that day,” the witness says. “What I need now is different.” They place a practical request beside the old record.\n\nThe old account and present request remain separate pieces on the table. You can listen to the day they describe and ask what assistance would help now. No practical promise needs to purchase forgiveness."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","22","scenes","0"],"field":"read","id":"chapter-character-aldric-3-1","title":"The record that can be checked","before":"The entry describes a body, a damaged hand, and a signet. Its conclusion is narrow: the subject continued living after departure; memory remained incomplete. The page also records what the writer could not explain.","after":"The entry describes a body, a damaged hand, and a signet. Its conclusion is narrow: the subject continued living after departure; memory remained incomplete. The page also records what the writer could not explain.\n\nThe writer's uncertainty remains on the same page as the identifying details. You can compare them with independent records before accepting the conclusion. The entry may describe your body without owning the meaning of your continued life."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","22","scenes","1"],"field":"read","id":"chapter-character-aldric-3-2","title":"A witness who was not in the room with the author","before":"The intermediary describes the transfer before seeing your copy. One detail matches. Another is something the ledger never mentioned. “I can tell you what I carried and where I left it. I cannot tell you everything he did afterward.”","after":"The intermediary describes the transfer before seeing your copy. One detail matches. Another is something the ledger never mentioned. “I can tell you what I carried and where I left it. I cannot tell you everything he did afterward.”\n\nThe unprompted detail gives you something to check outside the ledger. You can ask where the transfer ended and who witnessed it. What happened afterward remains open until another source can speak to it."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","23","scenes","0"],"field":"read","id":"chapter-character-aldric-4-1","title":"The record outside the office","before":"This page was not written for a magistrate. It concerns an ordinary purchase, an invitation, or a family favor. For once, the person at its center was doing something that had nothing to do with the Crown.","after":"This page was not written for a magistrate. It concerns an ordinary purchase, an invitation, or a family favor. For once, the person at its center was doing something that had nothing to do with the Crown.\n\nThe ordinary act can be examined without putting an official title at its center. You can ask how the page was kept and whose handwriting remains. A personal trace deserves its own evidence rather than a memory supplied to fill it."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","23","scenes","1"],"field":"read","id":"chapter-character-aldric-4-2","title":"Someone remembers something small","before":"The witness describes a habit no official file would need to record. Then they ask whether you want to hear more. The answer can be yes, later, or no.","after":"The witness describes a habit no official file would need to record. Then they ask whether you want to hear more. The answer can be yes, later, or no.\n\nThe offered choice leaves the witness free to pause as well as you. You can ask for one detail at a time or set the account aside. A family's story need not become a test you must finish immediately."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","24","scenes","0"],"field":"read","id":"chapter-character-aldric-5-1","title":"The help that is wanted","before":"The request is specific: preserve these records, escort this person, return what belongs to them, or make this place safer. Nobody asks you to become the person you were.","after":"The request is specific: preserve these records, escort this person, return what belongs to them, or make this place safer. Nobody asks you to become the person you were.\n\nEach proposed task has a person or place that can be helped now. You can ask what consent and limits it requires before accepting one. The work can be judged by what it changes, without demanding a new identity from you."},{"global":"ECHO_CHARACTER_CHAPTERS_DATA","path":["chapters","24","scenes","1"],"field":"read","id":"chapter-character-aldric-5-2","title":"An answer that does not ask permission","before":"When the question of debt returns, there is an answer available that needs no spell to enforce it: “You had a part in my return. You do not get to decide what I do with it.”","after":"When the question of debt returns, there is an answer available that needs no spell to enforce it: “You had a part in my return. You do not get to decide what I do with it.”\n\nThe available words can be spoken, revised, or left unsaid. You can decide what obligation you recognize and what authority you refuse. Another person's part in your survival does not settle your next choice."},{"global":"ECHO_SATELLITES_DATA","path":["sites","1","beats","0"],"field":"read","id":"satellite-library-offer","title":"Offer — three claims on one cellar","before":["Selise clears enough space on the counter for a deed, a damp-stained inventory and a carpenter’s sketch. “These disagree in useful ways,” she says. “Before anyone goes below, I would like us to agree what we are allowed to carry back.”"],"after":["Selise clears enough space on the counter for a deed, a damp-stained inventory and a carpenter’s sketch. “These disagree in useful ways,” she says. “Before anyone goes below, I would like us to agree what we are allowed to carry back.”","The damp stain and the carpenter's lines offer different kinds of evidence on the same counter. Selise leaves them where you can compare them. You can ask which parts may be copied and which objects must remain where they are found."]},{"global":"ECHO_SATELLITES_DATA","path":["sites","1","beats","1"],"field":"read","id":"satellite-library-entry","title":"Travel and entry — leave a way home","before":["The shop’s back room smells of paper and damp stone. Below the floor hatch, a line of steps disappears beyond the lantern’s reach. Evin leaves a chalk mark beside the latch. “This stays clear,” they say. “Whatever is down there, this is how we come back.”"],"after":["The shop’s back room smells of paper and damp stone. Below the floor hatch, a line of steps disappears beyond the lantern’s reach. Evin leaves a chalk mark beside the latch. “This stays clear,” they say. “Whatever is down there, this is how we come back.”","The hatch and chalk mark provide a return point before the stairs take you out of the shop's light. The smell of damp grows nearer below. You can check the opening and keep the landing clear before deciding who descends first."]},{"global":"ECHO_SATELLITES_DATA","path":["sites","1","beats","2"],"field":"read","id":"satellite-library-room-1","title":"Room 1 — the forgotten stair","before":["At the foot of the stair, the lantern catches a patch of stone worked rougher than the wall around it. Letters once stood here. Across the threshold lie empty desks, blank book spines and dust that has settled undisturbed beneath their legs."],"after":["At the foot of the stair, the lantern catches a patch of stone worked rougher than the wall around it. Letters once stood here. Across the threshold lie empty desks, blank book spines and dust that has settled undisturbed beneath their legs.","The rough patch interrupts the wall where writing has been removed. Dust beneath the desks records a quieter history than a spoken explanation would. You can examine the threshold, stone, and books without deciding who erased the letters."]},{"global":"ECHO_SATELLITES_DATA","path":["sites","1","beats","3"],"field":"read","id":"satellite-library-room-2","title":"Room 2 — the listening desks","before":["The first desk swallows the edges of your voice. A step away, the sound returns. Under its lamp rests a brass arm poised above an empty page, as if the reader had only just stepped out."],"after":["The first desk swallows the edges of your voice. A step away, the sound returns. Under its lamp rests a brass arm poised above an empty page, as if the reader had only just stepped out.","A single step separates the altered sound from ordinary speech. The brass arm and empty page remain visible beneath the lamp. You can mark that boundary and compare voices from either side without putting a hand into the mechanism."]},{"global":"ECHO_SATELLITES_DATA","path":["sites","1","beats","4"],"field":"read","id":"satellite-library-room-3","title":"Room 3 — the circular table","before":["Eight small name-slips surround a broad central hollow. Beside them, two columns have survived the damp: one headed “recorded,” the other “sounding.” Several rows end in space that nobody has filled."],"after":["Eight small name-slips surround a broad central hollow. Beside them, two columns have survived the damp: one headed “recorded,” the other “sounding.” Several rows end in space that nobody has filled.","The headings name two different columns, and the hollow leaves space at their center. You can copy the arrangement exactly, including the empty rows. Nothing in the surviving words tells you to fill those spaces or name whoever belongs there."]},{"global":"ECHO_SATELLITES_DATA","path":["sites","1","beats","5"],"field":"read","id":"satellite-library-room-4","title":"Room 4 — the sealed folio","before":["A waxed packet waits behind glass. The latch beside it is plain brass. Farther back, a second rod bears a warning in careful letters: “A reading is not a summons.” The two mechanisms are clearly separate."],"after":["A waxed packet waits behind glass. The latch beside it is plain brass. Farther back, a second rod bears a warning in careful letters: “A reading is not a summons.” The two mechanisms are clearly separate.","The glass, latch, and warning rod offer three features to inspect separately. The words on the rod are readable before anything is moved. You can ask which mechanism holds the packet without treating its contents as permission to operate the other."]},{"global":"ECHO_SATELLITES_DATA","path":["sites","1","beats","6"],"field":"read","id":"satellite-library-custody","title":"Decision — preserve, copy or relocate","before":["Back at the landing, a bead of water gathers under the lowest shelf. Selise holds out blank tags. Ressa has left space for signatures beneath her inventory. There is room for more than one name on each receipt."],"after":["Back at the landing, a bead of water gathers under the lowest shelf. Selise holds out blank tags. Ressa has left space for signatures beneath her inventory. There is room for more than one name on each receipt.","The gathering water gives the shelf a practical concern, while the blank tags leave handling undecided. You can name an owner, a keeper, and what each may do. More than one signature can preserve responsibility without making every object communal."]},{"global":"ECHO_SATELLITES_DATA","path":["sites","1","beats","7"],"field":"read","id":"satellite-library-return","title":"Return — test the missing-record method","before":["A clean table holds your sketch, the permitted copy and a sheet someone has deliberately left incomplete. Selise taps the empty line. “If we fill every gap because it looks untidy, we will never learn which gaps matter.”"],"after":["A clean table holds your sketch, the permitted copy and a sheet someone has deliberately left incomplete. Selise taps the empty line. “If we fill every gap because it looks untidy, we will never learn which gaps matter.”","The sketch and permitted copy can be checked against the account you brought back. The unfinished sheet keeps uncertainty visible. You can decide which gap deserves another visit and which information should remain with its owner."]},{"global":"ECHO_FINALE_DATA","path":["scenes","0"],"field":"read","id":"finale-three-briefs","title":"Three briefs before a decision","before":["There is room on the table for three accounts: what is being prepared below, who might be affected above, and what your proposed answers have actually demonstrated. The empty spaces are still visible. Nobody has filled them with a promise."],"after":["There is room on the table for three accounts: what is being prepared below, who might be affected above, and what your proposed answers have actually demonstrated. The empty spaces are still visible. Nobody has filled them with a promise.","The table allows each account to be read beside the others without collapsing them into one confident story. You can point to evidence, limits, and questions still open. Before choosing an intervention, there is time to ask what your plan has actually proved."]},{"global":"ECHO_FINALE_DATA","path":["scenes","1"],"field":"read","id":"finale-warning","title":"A warning people can use","before":["Someone has put two sketches beside each other. The old doorway is ordinary in one. In the other, made a few breaths later, its edge lies somewhere else. Beneath the drawings is a practical question: “If this happens again, who needs to know first?”"],"after":["Someone has put two sketches beside each other. The old doorway is ordinary in one. In the other, made a few breaths later, its edge lies somewhere else. Beneath the drawings is a practical question: “If this happens again, who needs to know first?”","The two outlines give you a visible difference to compare. You can note when each was drawn and who witnessed the change. A warning can travel with those details while leaving its explanation unsettled."]},{"global":"ECHO_FINALE_DATA","path":["scenes","2"],"field":"read","id":"finale-resident-meeting","title":"The people who live here","before":["The map is not the only thing on the table. There are work orders, a key tied to a ribbon, a basket that needs returning, and a list with spaces beside the names. Orenna taps the blank spaces. “Ask first. Then we can make a plan someone can actually use.”"],"after":["The map is not the only thing on the table. There are work orders, a key tied to a ribbon, a basket that needs returning, and a list with spaces beside the names. Orenna taps the blank spaces. “Ask first. Then we can make a plan someone can actually use.”","The key and basket give ordinary needs a place beside the map. Blank spaces next to names are invitations to ask, not orders already accepted. You can listen for a person's destination, load, and limits before adding them to the plan."]},{"global":"ECHO_FINALE_DATA","path":["scenes","3"],"field":"read","id":"finale-route-rehearsal","title":"Walk the way out","before":["The first turn looks simple until someone tries it with the load they actually intend to carry. A wheel catches. There is room to solve that now. Beyond it, the street continues into a city that still expects deliveries, meals and ordinary arrivals."],"after":["The first turn looks simple until someone tries it with the load they actually intend to carry. A wheel catches. There is room to solve that now. Beyond it, the street continues into a city that still expects deliveries, meals and ordinary arrivals.","The caught wheel identifies a problem at a particular turn. You can adjust the load, seek help, or choose another checked passage while there is time. The rehearsal belongs to the people using the route, whose needs may differ from an adventurer's."]},{"global":"ECHO_FINALE_DATA","path":["scenes","4"],"field":"read","id":"finale-controls","title":"At the reachable controls","before":["The marks on the drawing have counterparts here: a fitting, a line of wear, a place where someone changed the design. Some can be checked. Others disappear into work you have not yet seen. Before you touch anything, you can decide which claim you mean to test."],"after":["The marks on the drawing have counterparts here: a fitting, a line of wear, a place where someone changed the design. Some can be checked. Others disappear into work you have not yet seen. Before you touch anything, you can decide which claim you mean to test.","A fitting and its wear can be examined here without granting the drawing complete authority. The unexamined connections remain uncertain. You can name the specific part you intend to test and keep a way to stop before changing it."]},{"global":"ECHO_FINALE_DATA","path":["scenes","5"],"field":"read","id":"finale-negotiation","title":"The experiment he cannot bear to abandon","before":["Halaster clears a space as if you have arrived for an appointment he never doubted you would keep. “You have brought back so much,” he says. “Tell me you have brought something better than the advice to stop looking.”"],"after":["Halaster clears a space as if you have arrived for an appointment he never doubted you would keep. “You have brought back so much,” he says. “Tell me you have brought something better than the advice to stop looking.”","The cleared space makes an audience possible without making his invitation safe. Halaster waits for an answer to his own question. You can place evidence before him, ask what he is prepared to limit, or decline the terms he assumes you have brought."]},{"global":"ECHO_FINALE_DATA","path":["scenes","6"],"field":"read","id":"finale-verify-terms","title":"A promise becomes a checked action","before":["The words have stopped. Now there is a control to be checked, an observer waiting for a sign, and a route that must remain open. The next thing that matters is small enough for someone other than Halaster to verify."],"after":["The words have stopped. Now there is a control to be checked, an observer waiting for a sign, and a route that must remain open. The next thing that matters is small enough for someone other than Halaster to verify.","The observer and open route turn a spoken promise into something that can be checked. You can agree on the sign before operating the control. A failure to see it remains a reason to stop, even if the explanation sounds persuasive."]},{"global":"ECHO_FINALE_DATA","path":["scenes","7"],"field":"read","id":"finale-shutdown","title":"Interrupt, observe, secure","before":["You have named the first action, the sign that would mean it worked, and the sign that would mean you should stop. For once, the plan does not depend on the person who built the machine being right about everything."],"after":["You have named the first action, the sign that would mean it worked, and the sign that would mean you should stop. For once, the plan does not depend on the person who built the machine being right about everything.","Each named sign gives the next action a boundary. The plan still needs someone watching the result and someone able to call a halt. You can check those roles before touching the apparatus; a hopeful prediction does not replace the observed response."]},{"global":"ECHO_FINALE_DATA","path":["scenes","8"],"field":"read","id":"finale-limited-rescue","title":"The smallest honest attempt","before":["The agreed limit is written where everyone can see it. Beside it are the people who may call a stop and the words you will use if nothing answers. The empty place at the center has not been promised to anyone."],"after":["The agreed limit is written where everyone can see it. Beside it are the people who may call a stop and the words you will use if nothing answers. The empty place at the center has not been promised to anyone.","The written limit leaves no need to guess when the attempt has gone too far. The empty place remains empty while everyone checks the stopping words. You can confirm consent and an exit before asking any response to cross it."]},{"global":"ECHO_FINALE_DATA","path":["scenes","9"],"field":"read","id":"finale-activation","title":"When the change is happening now","before":["The change is here now. There are people to reach, exits to check, and an experiment that no longer exists only on paper. Where do you turn first?"],"after":["The change is here now. There are people to reach, exits to check, and an experiment that no longer exists only on paper. Where do you turn first?","The checked exits and people needing help give the moment practical priorities. You can name one person or one route before trying to solve the whole disturbance. What you see now must guide the next step, even if it differs from the rehearsal."]},{"global":"ECHO_FINALE_DATA","path":["scenes","10"],"field":"read","id":"finale-rescue-route","title":"One person, one obstacle, one way forward","before":["At this point the problem has a human scale: someone needs to get past something they cannot manage alone. There is room to ask what help they want, look at the route you checked, and decide what can be done now."],"after":["At this point the problem has a human scale: someone needs to get past something they cannot manage alone. There is room to ask what help they want, look at the route you checked, and decide what can be done now.","The obstacle can be inspected before help becomes an instruction. Ask how the person can move and what they need carried. A clear route matters more here than a dramatic promise, and a pause may reveal a safer way through."]},{"global":"ECHO_FINALE_DATA","path":["scenes","11"],"field":"read","id":"finale-custody","title":"What is kept, and by whom","before":["What you have brought here will need more than a place on a shelf. There is a question for each piece: who may keep it, who may use it, and who gets a say?"],"after":["What you have brought here will need more than a place on a shelf. There is a question for each piece: who may keep it, who may use it, and who gets a say?","A label can preserve the difference between an observation, a working tool, and something too uncertain to use. You can decide what remains sealed and whose consent another examination needs. Keeping a discovery does not require making it available to everyone."]},{"global":"ECHO_FINALE_DATA","path":["scenes","12"],"field":"read","id":"finale-aftermath","title":"Return to the lives that remain","before":["The next question is smaller than the one that brought you here. What do you need now, and what will you choose to do next?"],"after":["The next question is smaller than the one that brought you here. What do you need now, and what will you choose to do next?","There is room for a rest, a message, or a practical task before the larger story is told. You can choose who hears your account and what remains private. The next ordinary need deserves an answer of its own."]},{"global":"ECHO_STORY_DATA","path":["PHANDELVER_PACKS","0"],"field":"say","id":"phandalin","title":"Phandalin and its people","before":"The track opens onto a small frontier town built beside older ruins. People are working, trading, and watching the road for news.","after":"The track opens onto a small frontier town built beside older ruins. People are working, trading, and watching the road for news.\n\nThe open street gives you room to pause before choosing a doorway. Work continues around the older stone, and news from the road can draw attention. You can ask directions, seek lodging, or decide which errand deserves your first visit."},{"global":"ECHO_STORY_DATA","path":["PHANDELVER_PACKS","1"],"field":"say","id":"redbrand","title":"Redbrand Hideout","before":"The old manor has become a guarded base. The gang’s rule over town has consequences for people nearby.","after":"The ruined manor rises above a route leading down into cooler stone. Its damaged walls leave the entrance worth examining before you go farther.\n\nThe damaged stone and descending route give the approach a clear threshold. You can examine it before following the passage out of daylight. What waits beyond the first turn remains unseen from here."},{"global":"ECHO_STORY_DATA","path":["PHANDELVER_PACKS","2"],"field":"say","id":"spiders-web","title":"The Spider’s Web · branching leads","before":"Several leads point away from town. The party chooses which promise, rumor, or threat matters first.","after":"The countryside opens beyond the last houses, with roads and tracks leading away from the familiar streets. You can stop here to compare the route ahead with the directions you have been given.\n\nA road can be followed, a question checked, or an errand left for another day. You can compare your known landmarks with the account that brought you here. The map still has room for a route of your own choosing."},{"global":"ECHO_STORY_DATA","path":["PHANDELVER_PACKS","3"],"field":"say","id":"cragmaw-castle","title":"Cragmaw Castle","before":"A ruined stronghold holds competing interests around a missing dwarf and the route to the mine.","after":"A ruined stronghold rises above its approach. Its battered walls and broken towers leave gaps in the old outline, while the interiors remain hidden beyond the stone.\n\nBroken stone interrupts the outline of the stronghold, making its approach worth studying before you cross the open ground. You can watch the visible openings and choose where to stop. The walls conceal the rooms and people beyond them."},{"global":"ECHO_STORY_DATA","path":["PHANDELVER_PACKS","4"],"field":"say","id":"wave-echo","title":"Wave Echo Cave","before":"The old mine carries the sound of distant water. Its rooms hold both the immediate danger and a larger history.","after":"The old mine carries the sound of distant water. Cool air comes from the darkness ahead, where the entrance gives way to stone beyond the daylight.\n\nThe sound rises and fades through the stone without revealing its source. You can pause at the entrance to check the light, footing, and return landmark before continuing. An echo carries farther than a clear view into the mine."}];
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const paragraphs=value=>(Array.isArray(value)?value:[value]).flatMap(s=>String(s??'').split(/\n\s*\n/)).map(s=>s.trim()).filter(Boolean);
const byId=new Map();for(const e of entries){const key=e.id+'|'+e.field;if(!byId.has(key))byId.set(key,[]);byId.get(key).push(e);}
function upgradeBeat(beat){if(!beat||typeof beat!=='object')return beat;let result=beat;for(const field of ['read','readAfter']){for(const e of byId.get(beat.id+'|'+field)||[]){if(same(result[field],e.before)||(field==='read'&&typeof e.before==='string'&&Array.isArray(result[field])&&result[field].length===1&&result[field][0]===e.before)){if(result===beat)result={...beat};result[field]=Array.isArray(result[field])?paragraphs(e.after):structuredClone(e.after);break;}}}return result;}
function apply(){for(const e of entries){let object=globalThis[e.global];for(const part of e.path)object=object?.[part];if(object&&same(object[e.field],e.before))object[e.field]=structuredClone(e.after);}
 // Packs may already contain copied room narration. Match the original text as well as ID.
 for(const pack of Object.values(globalThis.ECHO_CONTENT_PACKS||{})){if(Array.isArray(pack?.runbook))pack.runbook=pack.runbook.map(upgradeBeat);}
}
globalThis.ECHO_NARRATION={version:1,entries,paragraphs,upgradeBeat,apply};apply();
})();
